const SHOP_FIT = { a: 730.9292, b: 0.4804, predict: x => 730.9292 * Math.pow(Math.max(x, 100), 0.4804), n: 764 };
// Previous 2026-only fits (81 days): AMZ a=25.70 b=0.82, SHOP a=5521.29 b=0.22
// Full-history fit increases Shopify elasticity from 0.22 → 0.48 — the optimizer
// will now shift more budget toward Shopify-driving channels (Google, Meta).
const WAL_ROAS = 10.16; // initial ROAS, diminishes with scale
const WAL_CEILING = 5000; // max daily Walmart revenue — small marketplace, limited catalog
function walRevenue(walSp) { return walSp > 0 ? WAL_CEILING * (1 - Math.exp(-walSp * WAL_ROAS / WAL_CEILING)) : 0; }
// ═══ SELF-IMPROVING MODEL ENGINE ═══
// Auto-refits power law coefficients on every data load.
// Tracks coefficient drift, prediction errors, and model confidence.

function fitPowerFull(pts) {
  const valid = pts.filter(p => p[0] > 0 && p[1] > 0);
  const n = valid.length;
  if (n < 10) return null;
  let sx=0, sy=0, sxx=0, sxy=0;
  for (const p of valid) {
    const lx = Math.log(p[0]), ly = Math.log(p[1]);
    sx+=lx; sy+=ly; sxx+=lx*lx; sxy+=lx*ly;
  }
  const b = (n*sxy - sx*sy) / (n*sxx - sx*sx);
  const a = Math.exp((sy - b*sx) / n);
  // R-squared
  const meanY = sy / n;
  let ssTot=0, ssRes=0;
  for (const p of valid) {
    const ly = Math.log(p[1]);
    const pred = Math.log(a) + b * Math.log(p[0]);
    ssTot += (ly - meanY) ** 2;
    ssRes += (ly - pred) ** 2;
  }
  const r2 = 1 - ssRes / ssTot;
  return { a, b, r2, n, predict: x => a * Math.pow(Math.max(x, 100), b) };
}

function trackModelHealth(actuals) {
  if (actuals.length < 30) return null;
  // Refit on all actuals
  const amzPts = actuals.filter(r => r[8] > 100 && r[5] > 5000).map(r => [r[8], r[5]]);
  const nonAmzPts = actuals.filter(r => (r[9]+r[10]+r[11]) > 50 && r[6] > 3000).map(r => [r[9]+r[10]+r[11], r[6]]);
  const amzRefit = fitPowerFull(amzPts);
  const shopRefit = fitPowerFull(nonAmzPts);
  
  // Compare refit params to static params
  const amzDrift = amzRefit ? { a: ((amzRefit.a - AMZ_FIT.a) / AMZ_FIT.a * 100), b: ((amzRefit.b - AMZ_FIT.b) / AMZ_FIT.b * 100) } : null;
  const shopDrift = shopRefit ? { a: ((shopRefit.a - SHOP_FIT.a) / SHOP_FIT.a * 100), b: ((shopRefit.b - SHOP_FIT.b) / SHOP_FIT.b * 100) } : null;

  // Prediction errors: last 14 days actual vs model prediction
  const recent = actuals.slice(-14);
  let sumErr = 0, sumAbsErr = 0, n = 0;
  const errors = [];
  for (const r of recent) {
    if (r[8] < 100) continue;
    const nonAmz = r[9] + r[10] + r[11];
    const predAmz = AMZ_FIT.predict(r[8]) + (14000 * (1 - Math.exp(-r[10] / 1000)));
    const predShop = SHOP_FIT.predict(nonAmz);
    const predTotal = predAmz + predShop + walRevenue(r[12]);
    const err = (predTotal - r[2]) / r[2] * 100;
    errors.push({ date: r[0], pred: predTotal, act: r[2], err });
    sumErr += err; sumAbsErr += Math.abs(err); n++;
  }
  const mape = n > 0 ? sumAbsErr / n : 0;
  const bias = n > 0 ? sumErr / n : 0;

  return {
    amzRefit, shopRefit, amzDrift, shopDrift,
    mape, bias, errors, n: actuals.length,
    status: mape < 15 ? "healthy" : mape < 25 ? "drifting" : "needs-refit"
  };
}


// Meta halo effect — drives Amazon branded search + Shopify direct
// Uses logistic saturation: strong initial halo, plateaus quickly
// HALO_CEILING = max daily Amazon rev lift from Meta awareness ($10K)
// HALO_HALF = Meta spend at which halo is 50% of ceiling ($600)
// At $600: ~$5K halo. At $2K: ~$9.2K. At $4K: ~$10K (saturated).
// Northbeam will replace this entire model with real attribution coefficients.
// Meta halo calibrated from 764-day residual analysis:
// Amazon actual minus power-law prediction, grouped by Meta spend.
// Positive residual of ~$14K peaks at Meta=$1500–$2000, saturates beyond.
// Ceiling = max avg residual at $1500+ Meta. Half = spend at 50% of ceiling.
const HALO_CEILING = 14000;
const HALO_HALF = 1000;
function metaHalo(metaSp) { return HALO_CEILING * (1 - Math.exp(-metaSp / HALO_HALF)); }

function projectRevenue(amzSp, gglSp, metaSp, msftSp, walSp) {
  // Platform revenue, not channel revenue
  const nonAmzSp = gglSp + metaSp + msftSp;
  const amzRev = AMZ_FIT.predict(amzSp) + metaHalo(metaSp); // Amazon platform + Meta halo (diminishing)
  const shopRev = SHOP_FIT.predict(nonAmzSp); // Shopify platform
  const walRev = walRevenue(walSp); // Walmart platform (logistic saturation)
  const total = amzRev + shopRev + walRev;
  return { total, amz: amzRev, shop: shopRev, wal: walRev, nonAmzSp, halo: metaHalo(metaSp) };
}

// ═══ MARGIN MODEL — calibrated from 17,773 orders (Nov 2025 – Mar 2026) ═══
// Source: Margin_by_Order_Historical_.csv summary rows
// Pre-ad margin = (Net Sales − Fees − Commission − Shipping − COGS) / Net Sales
// Revenue in optimizer = NET sales (post-discount), so margins are % of net.
const MARGIN = {
  amz: { cogs: 0.443, fees: 0.113, ship: 0.125, net: 0.318, n: 12182 },  // $9.0M net, $2.86M pre-ad (31.8%)
  shop: { cogs: 0.429, fees: 0.042, ship: 0.108, net: 0.422, n: 4140 },   // $4.5M net, $1.92M pre-ad (42.2%)
  wal: { cogs: 0.406, fees: 0.108, ship: 0.112, net: 0.374, n: 255 },     // $265K net, $99K pre-ad (37.4%)
  newCustPremium: 2.5, repeatShare: 0.35,
  // KEY FINDINGS:
  // 1. Amazon margin LOWER than previous estimate (31.8% vs 35.1%) — shipping costs higher than expected
  // 2. Shopify margin HIGHER than previous estimate (42.2% vs 34.7%) — previous used gross denominator, net is correct
  // 3. Amazon sub-$300 orders: 47% are NEGATIVE margin, $-28K total contribution
  //    Orders $800+: 33.5% margin, +$2.4M contribution — ad targeting should bias toward high-AOV
  // 4. Geekz Shopify: −$161K on $74K net sales — structurally unprofitable, excluded from optimizer
  // 5. Sven Shopify discounts are 4.4% of gross ($248K) — NOT 46% (that was order-level parsing artifact)
  amzTiers: { sub300: { share: 0.43, margin: -0.03, n: 4901 }, mid: { share: 0.21, margin: 0.144, n: 2380 }, high: { share: 0.36, margin: 0.335, n: 4215 } },
};

function projectContribution(amzSp, gglSp, metaSp, msftSp, walSp) {
  const rev = projectRevenue(amzSp, gglSp, metaSp, msftSp, walSp);
  const totalSp = amzSp + gglSp + metaSp + msftSp + walSp;
  // Amazon margin adjusted for AOV mix: high-AOV orders (>$800) are 33.5% margin,
  // low-AOV (sub-$300) are -3% margin. Blended depends on ad targeting.
  // Conservative: use blended 31.8% from actual order data.
  const amzContrib = rev.amz * MARGIN.amz.net - amzSp;
  const shopContrib = rev.shop * MARGIN.shop.net - (gglSp + metaSp + msftSp);
  const walContrib = rev.wal * MARGIN.wal.net - walSp;
  const gross = amzContrib + shopContrib + walContrib;
  const newShare = 1 - MARGIN.repeatShare;
  const ltvAdj = gross * (MARGIN.repeatShare + newShare * MARGIN.newCustPremium);
  return { ...rev, amzContrib, shopContrib, walContrib, grossContrib: gross, ltvContrib: ltvAdj, totalSp };
}

