// ═══ TIME SERIES FORECAST ENGINE ═══
function buildForecast(acts) {
  if (!acts || acts.length < 14) return null;
  const dowMap = { Sun:0, Mon:1, Tue:2, Wed:3, Thu:4, Fri:5, Sat:6 };
  const dowR = [0,0,0,0,0,0,0], dowS = [0,0,0,0,0,0,0], dowN = [0,0,0,0,0,0,0];
  acts.forEach(r => { const d = dowMap[r[1]]; dowR[d] += r[2]; dowS[d] += r[3]; dowN[d]++; });
  const avgR = acts.reduce((s,r) => s + r[2], 0) / acts.length;
  const avgS = acts.reduce((s,r) => s + r[3], 0) / acts.length;
  const dowRC = dowR.map((s,i) => dowN[i] > 0 ? s/dowN[i]/avgR : 1);
  const dowSC = dowS.map((s,i) => dowN[i] > 0 ? s/dowN[i]/avgS : 1);
  // Deseasonalized trend: remove DOW effect and promo multiplier before fitting
  const rec = acts.slice(-30);
  const n = rec.length;
  let sx=0, sy=0, sxx=0, sxy=0;
  rec.forEach((r,i) => {
    const dow = dowMap[r[1]];
    const dowFactor = dowRC[dow] || 1;
    const promoMult = getSpendMultiplier(r[0], 7, 1.5).mult;
    // Strip DOW + promo seasonality to isolate true trend
    const deseason = r[2] / dowFactor / Math.max(promoMult, 0.8);
    sx+=i; sy+=deseason; sxx+=i*i; sxy+=i*deseason;
  });
  const slope = (n*sxy - sx*sy) / (n*sxx - sx*sx);
  const intercept = (sy - slope*sx) / n;
  return { dowRC, dowSC, slope, intercept, avgR, avgS, n, nTotal: acts.length,
    predict: (dayIdx, dow, spLvl) => {
      const base = intercept + slope * (n + dayIdx);
      return Math.max(0, base * (dowRC[dow]||1) * (spLvl > 0 ? Math.pow(spLvl/avgS, 0.82) : 1));
    }
  };
}

// ═══ ANOMALY DETECTION ═══
function detectAnomalies(acts) {
  if (acts.length < 28) return [];
  const anoms = [];
  const recent = acts.slice(-7);
  const dowMap = { Sun:0, Mon:1, Tue:2, Wed:3, Thu:4, Fri:5, Sat:6 };
  const baseline = acts.slice(0, -7);
  recent.forEach(r => {
    const dow = dowMap[r[1]];
    const sameDow = baseline.filter(b => dowMap[b[1]] === dow).slice(-8);
    if (sameDow.length < 3) return;
    const avgR = sameDow.reduce((s,b) => s+b[2], 0) / sameDow.length;
    const stdR = Math.sqrt(sameDow.reduce((s,b) => s+Math.pow(b[2]-avgR,2), 0) / sameDow.length);
    const avgC = sameDow.reduce((s,b) => s+(b[31]||0), 0) / sameDow.length;
    const avgM = sameDow.reduce((s,b) => s+b[4], 0) / sameDow.length;
    const avgS = sameDow.reduce((s,b) => s+b[3], 0) / sameDow.length;
    const z = stdR > 0 ? (r[2]-avgR)/stdR : 0;
    if (z < -1.5) {
      const cD = avgC > 0 && r[31] > 0 ? (r[31]-avgC)/avgC*100 : 0;
      const sD = avgS > 0 && r[3] > 0 ? (r[3]-avgS)/avgS*100 : 0;
      let cause = "Organic traffic decline — check rankings";
      if (cD < -20) cause = "CVR collapse — listing suppression or competitor action";
      else if (sD < -15) cause = "Spend under-delivery — budget caps or disapprovals";
      else if (r[4] > avgM * 1.3) cause = "MER spike — spend elevated, revenue lagging";
      anoms.push({ date: r[0], sev: z < -2 ? "critical" : "warning", z: z.toFixed(1), cause, exp: avgR, act: r[2] });
    }
    if (z > 2) anoms.push({ date: r[0], sev: "info", z: z.toFixed(1), cause: "Revenue spike — investigate driver", exp: avgR, act: r[2] });
  });
  return anoms;
}

// ═══ INCREMENTALITY GEO-LIFT FRAMEWORK ═══
// Power analysis: MDE = 2.8 * stddev / sqrt(n_days) at 80% power, 95% confidence
function geoLiftPower(avgDailyRev, cv, days) {
  const mde = 2.8 * (avgDailyRev * cv) / Math.sqrt(days);
  const mdePct = mde / avgDailyRev * 100;
  return { mde: Math.round(mde), mdePct: Math.round(mdePct * 10) / 10, avgDailyRev, cv, days };
}

