// ═══ NORTHBEAM INTEGRATION SCHEMA ═══
// API: https://api.northbeam.io/v1/exports
// Auth: Basic auth with API key + Data-Client-ID header
// Data we need daily:
//   - Attributed Revenue per platform (Amazon, Google, Meta, MSFT) at ad level
//   - Attribution model: "Clicks + Modeled Views" (northbeam_custom__va)
//   - Attribution window: 7-day (captures conversion lag)
//   - Accounting mode: Accrual (credits revenue to ad impression date)
//   - Time granularity: daily
//   - Breakdowns: Platform, Campaign
// What this replaces in our model:
//   - SHOP_FIT power law → real per-channel Shopify attributed revenue curves
//   - metaHalo logistic → real Meta attributed Amazon revenue (MTA cross-platform)
//   - Conservative Google/MSFT multipliers → actual conversion data
//   - CH_MINS operational guesses → data-driven floor detection
const TRENDS = {"1/1":82,"1/5":66,"1/12":69,"1/19":70,"1/26":64,"2/1":64,"2/2":71,"2/9":65,"2/16":73,"2/23":72,"3/1":72,"3/2":68,"3/9":59,"3/16":63,"3/23":60,"3/30":61,"4/6":58,"4/13":57,"4/20":60,"4/27":59,"5/1":59,"5/4":57,"5/11":65,"5/18":67,"5/25":76,"6/1":64,"6/8":61,"6/10":61,"6/15":68,"6/22":67,"6/29":76,"7/6":71,"7/8":71,"7/13":66,"7/20":68,"7/24":68,"7/27":72,"8/3":74,"8/10":76,"8/17":74,"8/19":74,"8/24":76,"8/31":85,"9/7":64,"9/14":60,"9/16":60,"9/21":62,"9/28":66,"10/5":60,"10/12":63,"10/15":63,"10/19":58,"10/26":65,"11/2":71,"11/5":71,"11/9":74,"11/16":75,"11/23":100,"11/30":78,"12/6":78,"12/7":63,"12/14":56,"12/21":72,"12/28":85};

function parseMD(s) { const p = s.split("/"); return [parseInt(p[0]), parseInt(p[1])]; }
function dayOfYear(m, d) { const days = [0,31,28,31,30,31,30,31,31,30,31,30,31]; let r = d; for (let i = 1; i < m; i++) r += days[i]; return r; }

function getPromoContext(dateStr) {
  const [m, d] = parseMD(dateStr);
  const doy = dayOfYear(m, d);
  // Find matching promo
  for (const p of PROMOS) {
    const [sm, sd] = parseMD(p.start);
    const [em, ed] = parseMD(p.end);
    const startDoy = dayOfYear(sm, sd);
    const endDoy = dayOfYear(em, ed);
    if (doy >= startDoy && doy <= endDoy) {
      const progress = (doy - startDoy) / Math.max(endDoy - startDoy, 1);
      // Find nearest trends value
      const trendKey = m + "/" + d;
      let trend = 65;
      for (const k in TRENDS) { const [tm, td] = parseMD(k); if (dayOfYear(tm, td) <= doy) trend = TRENDS[k]; }
      return { promo: p.name, phase: progress < 0.15 ? "lead-in" : progress > 0.85 ? "lead-out" : "peak", progress, trend, code: p.code || null };
    }
  }
  return { promo: null, phase: "off", progress: 0, trend: 60, code: null };
}

function getSpendMultiplier(dateStr, leadInDays, maxMult) {
  const ctx = getPromoContext(dateStr);
  if (!ctx.promo) return { mult: 1, ctx };
  const trendFactor = ctx.trend / 70; // normalize around median
  let mult = 1;
  if (ctx.phase === "lead-in") {
    mult = 1 + (maxMult - 1) * Math.pow(ctx.progress / 0.15, 1.5) * trendFactor * 0.6;
  } else if (ctx.phase === "peak") {
    const peakShape = 1 - 0.2 * Math.pow(2 * ((ctx.progress - 0.15) / 0.7) - 1, 2);
    mult = 1 + (maxMult - 1) * peakShape * trendFactor;
  } else { // lead-out
    const decay = 1 - ((ctx.progress - 0.85) / 0.15);
    mult = 1 + (maxMult * 0.3 - 0.3) * decay * trendFactor;
  }
  return { mult: Math.max(1, Math.min(mult, maxMult)), ctx };
}

// ═══ RECOMMENDATION ENGINE v2 ═══
// Minimum budget floors — below these, organic rankings/feed visibility collapse
// These are operational constraints, not model outputs
const CH_MINS = { amz: 8000, ggl: 800, meta: 200, msft: 0, wal: 0 };

function recommendAllocation(totalBudget, maxMER, fcRev, spendMult) {
  const adjusted = totalBudget * spendMult;
  const mix = { amz: 0.80, ggl: 0.12, meta: 0.04, msft: 0.025, wal: 0.015 };
  let best = { amz: Math.round(adjusted * mix.amz), ggl: Math.round(adjusted * mix.ggl), meta: Math.round(adjusted * mix.meta), msft: Math.round(adjusted * mix.msft), wal: Math.round(adjusted * mix.wal) };
  let bestScore = -Infinity;
  const effectiveCeiling = spendMult > 1.05 ? maxMER * (1 + (spendMult - 1) * 0.3) : maxMER;
  for (let iter = 0; iter < 50; iter++) {
    const chs = ["amz", "ggl", "meta", "msft", "wal"];
    let improved = false;
    for (let i = 0; i < chs.length; i++) {
      for (let j = 0; j < chs.length; j++) {
        if (i === j) continue;
        const test = { ...best };
        const shift = chs[i] === "amz" ? 500 : 100;
        if (test[chs[i]] - shift < CH_MINS[chs[i]]) continue;
        test[chs[i]] -= shift;
        test[chs[j]] += shift;
        const c = projectContribution(test.amz, test.ggl, test.meta, test.msft, test.wal);
        const sp = c.totalSp;
        const mer = sp > 0 ? (sp / c.total * 100) : 100;
        // Optimize on LTV-adjusted contribution margin, not raw revenue
        if (c.ltvContrib > bestScore && mer <= effectiveCeiling) { bestScore = c.ltvContrib; best = test; improved = true; }
      }
    }
    if (!improved) break;
  }
  const c = projectContribution(best.amz, best.ggl, best.meta, best.msft, best.wal);
  const sp = c.totalSp;
  return { ...best, totalRev: c.total, totalSp: sp, mer: sp > 0 ? (sp / c.total * 100) : 0, roas: sp > 0 ? c.total / sp : 0, revDelta: c.total - fcRev, effectiveCeiling,
    grossContrib: c.grossContrib, ltvContrib: c.ltvContrib, amzContrib: c.amzContrib, shopContrib: c.shopContrib, walContrib: c.walContrib,
    subChannels: { amz: SUB_CH.amz.map(s => ({...s, budget: Math.round(best.amz * s.share)})), ggl: SUB_CH.ggl.map(s => ({...s, budget: Math.round(best.ggl * s.share)})), meta: SUB_CH.meta.map(s => ({...s, budget: Math.round(best.meta * s.share)})), msft: SUB_CH.msft.map(s => ({...s, budget: Math.round(best.msft * s.share)})) }
  };
}

function fm(n) { if (!n) return "$0"; if (Math.abs(n) >= 1e6) return "$" + (n/1e6).toFixed(1) + "M"; if (Math.abs(n) >= 1e3) return "$" + (n/1e3).toFixed(1) + "K"; return "$" + Math.round(n); }
function fk(n) { return "$" + Math.round(n || 0).toLocaleString(); }
function fc(n) { if (!n) return "—"; if (Math.abs(n) >= 1e6) return "$" + (n/1e6).toFixed(1) + "m"; if (Math.abs(n) >= 1e3) return "$" + (n/1e3).toFixed(1) + "k"; return "$" + Math.round(n); }
function pc(n) { return n === 0 ? "0%" : (n > 0 ? "+" : "") + n.toFixed(1) + "%"; }
function yoy(a, b) { return b > 0 ? ((a - b) / b * 100) : 0; }
function has(r) { return r[2] > 0; }

