function Tip({ active, payload, label }) {
  if (!active || !payload?.length) return null;
  return (
    <div style={{ background: T.cd, border: "1px solid " + T.bd, borderRadius: 8, padding: "8px 12px", fontSize: 11 }}>
      <div style={{ color: T.t2, marginBottom: 4, fontWeight: 600 }}>{label}</div>
      {payload.map((p, i) => (
        <div key={i} style={{ display: "flex", gap: 6, marginBottom: 2, alignItems: "center" }}>
          <span style={{ width: 7, height: 7, borderRadius: "50%", background: p.color, flexShrink: 0 }} />
          <span style={{ color: T.t2 }}>{p.name}:</span>
          <span style={{ color: T.tx, fontWeight: 600, fontFamily: "'JetBrains Mono', monospace", fontSize: 10 }}>
            {typeof p.value === "number" ? (Math.abs(p.value) > 100 ? fk(p.value) : p.value.toFixed(1) + "%") : p.value}
          </span>
        </div>
      ))}
    </div>
  );
}

function Metric({ label, actual, forecast, ly, color, isMER }) {
  const d = actual - forecast;
  const dp = forecast > 0 ? (d / forecast * 100) : 0;
  const lyD = ly > 0 ? yoy(actual, ly) : null;
  return (
    <div style={{ flex: 1, minWidth: 0 }}>
      <div style={{ fontSize: 9, color: T.t3, textTransform: "uppercase", letterSpacing: .4, fontWeight: 600, marginBottom: 4 }}>{label}</div>
      <div style={{ fontSize: 18, fontWeight: 700, fontFamily: "'JetBrains Mono', monospace", color: color }}>{isMER ? actual.toFixed(1) + "%" : fm(actual)}</div>
      {!isMER && (
        <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginTop: 3 }}>
          <span style={{ fontSize: 9, color: T.am }}>Fc: {fm(forecast)}</span>
          <span style={{ fontSize: 9, fontWeight: 600, padding: "0 4px", borderRadius: 3, background: (d >= 0 ? (label.includes("Spend") ? T.rd : T.gn) : (label.includes("Spend") ? T.gn : T.rd)) + "18", color: d >= 0 ? (label.includes("Spend") ? T.rd : T.gn) : (label.includes("Spend") ? T.gn : T.rd) }}>{pc(dp)}</span>
          {lyD !== null && <span style={{ fontSize: 9, color: T.pu }}>LY: {pc(lyD)}</span>}
        </div>
      )}
    </div>
  );
}

