// Hourly cumulative distribution curves (% of daily total expected by each hour)
// Based on typical DTC ecommerce patterns: slow morning, lunch bump, evening peak
const HOURLY_REV = [0,1,2,3,4,5,7,10,14,19,25,32,40,48,55,62,69,76,82,87,91,94,97,99,100];
const HOURLY_SPEND = [0,2,4,6,8,11,14,18,22,27,32,38,44,50,56,62,68,74,80,85,89,93,96,98,100];

function getExpectedPct(hour, type) {
  const curve = type === "spend" ? HOURLY_SPEND : HOURLY_REV;
  const h = Math.max(0, Math.min(24, Math.floor(hour)));
  return curve[h] / 100;
}

// Simulate hourly actuals from daily total using curve + random variance
// In production, this is replaced by real intraday API data
function simulateHourlyLog(dailyTotal, forecast, type, upToHour) {
  const curve = type === "spend" ? HOURLY_SPEND : HOURLY_REV;
  const hours = [];
  for (let h = 0; h < upToHour; h++) {
    const slicePct = (curve[h + 1] - curve[h]) / 100;
    const expected = forecast * slicePct;
    // Simulate with variance: some hours beat, some miss
    const variance = [1.12, 0.75, 1.05, 0.88, 1.15, 0.92, 1.08, 0.70, 1.20, 0.95, 1.02, 0.82, 1.10, 0.90, 1.05, 0.78, 1.15, 0.88, 1.0, 0.95, 1.05, 1.0, 0.98, 1.02];
    const actual = expected * (variance[h] || 1);
    const delta = actual - expected;
    const isMiss = expected > 0 && (actual / expected) < 0.82;
    hours.push({ hour: h, expected: Math.round(expected), actual: Math.round(actual), delta: Math.round(delta), pct: expected > 0 ? Math.round(actual / expected * 100) : 0, isMiss });
  }
  return hours;
}

function getPacingStatus(actual, forecast, ly, type, currentHour) {
  const hour = currentHour || 14;
  const expectedPct = getExpectedPct(hour, type);
  const expectedNow = forecast * expectedPct;
  const pacingPct = expectedNow > 0 ? (actual / expectedNow * 100) : 0;
  const eodProjected = expectedPct > 0 ? actual / expectedPct : 0;
  const eodDelta = eodProjected - forecast;
  const gap = actual - expectedNow;
  const lyPct = ly > 0 ? (actual / ly * 100) : 0;
  const isSpend = type === "spend";
  const remaining = forecast - actual;
  const hoursLeft = 24 - hour;

  const hourlyLog = simulateHourlyLog(actual, forecast, type, hour);
  const misses = hourlyLog.filter(h => h.isMiss);

  let status, color, bg, icon, insights = [];

  if (isSpend) {
    if (pacingPct <= 88) { status = "Under-delivering"; color = T.cy; bg = T.cy + "12"; icon = "↓"; }
    else if (pacingPct <= 105) { status = "On track"; color = T.gn; bg = T.gn + "12"; icon = "✓"; }
    else if (pacingPct <= 120) { status = "Running hot"; color = T.am; bg = T.am + "12"; icon = "⚠"; }
    else { status = "Over-pacing"; color = T.rd; bg = T.rd + "12"; icon = "✖"; }

    if (pacingPct > 120) {
      insights.push({ text: "Projecting " + fm(Math.abs(eodDelta)) + " over budget by EOD at current rate", type: "alert" });
      insights.push({ text: "Reduce bids on low-ROAS campaigns or pause bottom 10% ad groups", type: "action" });
      insights.push({ text: "Apply daypart modifiers to cap spend for remaining " + hoursLeft + " hours", type: "action" });
    } else if (pacingPct > 105) {
      insights.push({ text: "Trending " + fm(Math.abs(gap)) + " ahead of expected spend at " + hour + ":00", type: "alert" });
      insights.push({ text: "Amazon auto campaigns may be the driver — check search term reports", type: "action" });
    } else if (pacingPct < 88) {
      insights.push({ text: "Only " + Math.round(pacingPct) + "% of expected spend delivered by " + hour + ":00", type: "alert" });
      insights.push({ text: "Check campaign budget caps and billing status across platforms", type: "action" });
      insights.push({ text: "Increase bids on top performers to capture available demand", type: "action" });
    } else {
      insights.push({ text: "Spend on pace — projected EOD: " + fm(eodProjected) + " vs " + fm(forecast) + " plan", type: "ok" });
      insights.push({ text: "Maintain current bids. Next check-in: " + Math.min(hour + 3, 23) + ":00", type: "ok" });
    }
  } else {
    if (pacingPct >= 115) { status = "Ahead of pace"; color = T.gn; bg = T.gn + "12"; icon = "↑"; }
    else if (pacingPct >= 92) { status = "On track"; color = T.gn; bg = T.gn + "12"; icon = "✓"; }
    else if (pacingPct >= 80) { status = "Slightly behind"; color = T.am; bg = T.am + "12"; icon = "⚠"; }
    else { status = "At risk"; color = T.rd; bg = T.rd + "12"; icon = "✖"; }

    if (pacingPct < 80) {
      const needPerHour = hoursLeft > 0 ? (forecast - actual) / hoursLeft : 0;
      insights.push({ text: "Need " + fm(needPerHour) + "/hr for remaining " + hoursLeft + "hrs to hit " + fm(forecast), type: "alert" });
      insights.push({ text: "Check Amazon BSR and listing health for conversion drops", type: "action" });
      insights.push({ text: "Scale Meta/Google prospecting to drive incremental traffic", type: "action" });
    } else if (pacingPct < 92) {
      insights.push({ text: "Slightly below pace at " + hour + ":00 — projected EOD: " + fm(eodProjected), type: "alert" });
      insights.push({ text: "Evening peak (6–10pm) delivers ~" + Math.round(HOURLY_REV[22] - HOURLY_REV[18]) + "% of daily rev — may recover", type: "ok" });
      insights.push({ text: "Review Shopify cart abandonment for afternoon session quality", type: "action" });
    } else if (pacingPct >= 115) {
      insights.push({ text: "Projecting " + fm(eodProjected) + " EOD (" + fm(eodDelta) + " above forecast)", type: "ok" });
      insights.push({ text: "Strong demand — increase spend caps to capture momentum", type: "action" });
    } else {
      insights.push({ text: "Pacing within band — projected EOD: " + fm(eodProjected), type: "ok" });
      insights.push({ text: Math.round(100 - HOURLY_REV[hour]) + "% of daily rev typically comes after " + hour + ":00", type: "ok" });
    }
  }

  // Append hourly miss insights
  if (misses.length > 0) {
    const worstMiss = misses.reduce((w, m) => m.pct < w.pct ? m : w, misses[0]);
    const missHours = misses.map(m => m.hour + ":00").join(", ");
    const totalShortfall = misses.reduce((s, m) => s + Math.abs(m.delta), 0);
    insights.push({ text: misses.length + " hour(s) underperformed: " + missHours + " (−" + fm(totalShortfall) + " cumulative shortfall)", type: "log" });
    insights.push({ text: "Worst: " + worstMiss.hour + ":00 hit " + worstMiss.pct + "% of expected (exp " + fm(worstMiss.expected) + ", got " + fm(worstMiss.actual) + ") — check " + (isSpend ? "budget delivery" : "conversion rate and traffic") + " during this window", type: "log" });
    if (!isSpend && misses.some(m => m.hour >= 10 && m.hour <= 14)) {
      insights.push({ text: "Midday slump detected (10am–2pm) — review Amazon suppressed listings, Shopify site speed, and Meta ad fatigue", type: "action" });
    }
    if (!isSpend && misses.some(m => m.hour >= 6 && m.hour <= 9)) {
      insights.push({ text: "Morning underperformance (6–9am) — check Google Shopping feed issues and Amazon Buy Box status", type: "action" });
    }
    if (isSpend && misses.some(m => m.hour >= 8 && m.hour <= 12)) {
      insights.push({ text: "Spend delivery gap in peak hours — Amazon budget may have hit daily cap early, check campaign status", type: "action" });
    }
  }

  return { status, color, bg, icon, insights, pct: Math.round(pacingPct), eodProjected: Math.round(eodProjected), expectedPct: Math.round(expectedPct * 100), expectedNow: Math.round(expectedNow), hour, hourlyLog, misses };
}

function DualRingPie({ id, outerData, innerData, outerColors, innerColors, height }) {
  const h = height || 190;
  const oR = Math.round(h * 0.4);
  const oIR = Math.round(h * 0.28);
  const iR = Math.round(h * 0.26);
  const iIR = Math.round(h * 0.12);
  const oMid = Math.round((oR + oIR) / 2);
  const iMid = Math.round((iR + iIR) / 2);
  return (
    <div style={{ position: "relative" }}>
      <ResponsiveContainer width="100%" height={h}>
        <PieChart>
          <Pie data={outerData} dataKey="value" cx="50%" cy="50%" outerRadius={oR} innerRadius={oIR} paddingAngle={2} strokeWidth={0}>
            {outerColors.map((c, i) => ( <Cell key={i} fill={c} fillOpacity={0.25} /> ))}
          </Pie>
          <Pie data={innerData} dataKey="value" cx="50%" cy="50%" outerRadius={iR} innerRadius={iIR} paddingAngle={2} strokeWidth={0}>
            {innerColors.map((c, i) => ( <Cell key={i} fill={c} /> ))}
          </Pie>
          <Tooltip formatter={(v) => fk(v)} contentStyle={{ background: T.cd, border: "1px solid " + T.bd, borderRadius: 6, fontSize: 10, color: T.tx }} />
        </PieChart>
      </ResponsiveContainer>
      <svg viewBox="0 0 200 200" preserveAspectRatio="xMidYMid meet" style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%", pointerEvents: "none" }}>
        <defs>
          <path id={id + "_fo"} d={"M " + (100 - oMid) + " 100 A " + oMid + " " + oMid + " 0 0 1 " + (100 + oMid) + " 100"} />
          <path id={id + "_fi"} d={"M " + (100 - iMid) + " 100 A " + iMid + " " + iMid + " 0 0 1 " + (100 + iMid) + " 100"} />
        </defs>
        <text fontSize="8" fill={T.t3} fontFamily="'Outfit', sans-serif" fontWeight="500" letterSpacing="2">
          <textPath href={"#" + id + "_fo"} startOffset="50%" textAnchor="middle">FORECAST</textPath>
        </text>
        <text fontSize="8" fill={T.tx} fontFamily="'Outfit', sans-serif" fontWeight="600" letterSpacing="1.5">
          <textPath href={"#" + id + "_fi"} startOffset="50%" textAnchor="middle">ACTUAL</textPath>
        </text>
      </svg>
    </div>
  );
}

function StatusBadge({ s }) {
  return (
    <div style={{ display: "inline-flex", alignItems: "center", gap: 4, padding: "2px 8px", borderRadius: 4, background: s.bg, fontSize: 10, fontWeight: 700, color: s.color }}>
      <span style={{ fontSize: 11 }}>{s.icon}</span> {s.status}
    </div>
  );
}

function InsightPanel({ insights, color, hourlyLog, misses }) {
  const [showLog, setShowLog] = useState(false);
  return (
    <div style={{ marginTop: 10 }}>
      {/* Insights */}
      <div style={{ padding: "8px 10px", borderRadius: 6, background: T.cd, borderLeft: "2px solid " + color }}>
        <div style={{ fontSize: 9, color: T.t3, textTransform: "uppercase", letterSpacing: .5, fontWeight: 600, marginBottom: 4 }}>Recommended actions</div>
        {insights.map((ins, i) => {
          const isLog = ins.type === "log";
          const isAlert = ins.type === "alert";
          const ic = isLog ? "⏱" : isAlert ? "⚠" : ins.type === "action" ? "▸" : "✓";
          const icColor = isLog ? T.am : isAlert ? T.rd : ins.type === "action" ? color : T.gn;
          return (
            <div key={i} style={{ display: "flex", gap: 6, alignItems: "flex-start", marginBottom: i < insights.length - 1 ? 4 : 0, padding: isLog ? "3px 0" : 0, borderTop: isLog && i > 0 && insights[i-1].type !== "log" ? "1px dashed " + T.bd : "none", marginTop: isLog && i > 0 && insights[i-1].type !== "log" ? 4 : 0 }}>
              <span style={{ color: icColor, fontSize: isLog ? 10 : 8, marginTop: isLog ? 0 : 2, flexShrink: 0 }}>{ic}</span>
              <span style={{ fontSize: 10, color: isLog ? T.am : T.t2, lineHeight: 1.4, fontWeight: isLog ? 500 : 400 }}>{ins.text}</span>
            </div>
          );
        })}
      </div>
      {/* Hourly log toggle */}
      {hourlyLog && hourlyLog.length > 0 && (
        <div style={{ marginTop: 6 }}>
          <button onClick={() => setShowLog(!showLog)} style={{ background: "none", border: "none", cursor: "pointer", fontSize: 9, color: T.t3, fontFamily: "'Outfit', sans-serif", padding: 0, display: "flex", alignItems: "center", gap: 4 }}>
            <span>{showLog ? "▾" : "▸"}</span> {showLog ? "Hide" : "Show"} hourly log ({misses.length} miss{misses.length !== 1 ? "es" : ""})
          </button>
          {showLog && (
            <div style={{ marginTop: 6, padding: "6px 0", display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(52px, 1fr))", gap: 3 }}>
              {hourlyLog.map((h, i) => (
                <div key={i} style={{ textAlign: "center", padding: "4px 2px", borderRadius: 4, background: h.isMiss ? T.rd + "15" : h.pct > 110 ? T.gn + "10" : T.bg, border: "1px solid " + (h.isMiss ? T.rd + "30" : T.bd) }}>
                  <div style={{ fontSize: 8, color: T.t3, marginBottom: 1 }}>{h.hour}:00</div>
                  <div style={{ fontSize: 10, fontWeight: 600, fontFamily: "'JetBrains Mono', monospace", color: h.isMiss ? T.rd : h.pct > 110 ? T.gn : T.t2 }}>{h.pct}%</div>
                  <div style={{ fontSize: 8, fontFamily: "'JetBrains Mono', monospace", color: h.delta >= 0 ? T.gn : T.rd }}>{h.delta >= 0 ? "+" : ""}{fm(h.delta)}</div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function ProgressBar({ actual, forecast, color, label }) {
  const pct = forecast > 0 ? Math.min((actual / forecast) * 100, 150) : 0;
  const over = actual > forecast;
  return (
    <div style={{ marginBottom: 6 }}>
      <div style={{ display: "flex", justifyContent: "space-between", fontSize: 9, color: T.t3, marginBottom: 3 }}>
        <span>{label}</span>
        <span style={{ fontFamily: "'JetBrains Mono', monospace", color: over ? T.rd : T.gn, fontWeight: 600 }}>{pct.toFixed(0)}%</span>
      </div>
      <div style={{ height: 6, borderRadius: 3, background: T.bg, overflow: "hidden", position: "relative" }}>
        <div style={{ position: "absolute", left: 0, top: 0, height: "100%", width: Math.min(pct, 100) + "%", background: color, borderRadius: 3, transition: "width .5s" }} />
        {forecast > 0 && <div style={{ position: "absolute", left: "100%", top: -2, width: 1, height: 10, background: T.am }} />}
      </div>
    </div>
  );
}

function MiniSpark({ data, dataKey, color, height = 40 }) {
  return (
    <ResponsiveContainer width="100%" height={height}>
      <AreaChart data={data} margin={{ top: 2, right: 2, bottom: 2, left: 2 }}>
        <defs><linearGradient id={"g_" + dataKey + color.replace("#","")} x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor={color} stopOpacity={0.3} /><stop offset="95%" stopColor={color} stopOpacity={0} /></linearGradient></defs>
        <Area type="monotone" dataKey={dataKey} stroke={color} strokeWidth={1.5} fill={"url(#g_" + dataKey + color.replace("#","") + ")"} dot={false} />
      </AreaChart>
    </ResponsiveContainer>
  );
}

export default function SpendCommandCenter() {
  const [chV, setChV] = useState(null);
  const [expanded, setExpanded] = useState(null);
  const [budgets, setBudgets] = useState({ amz: 14000, ggl: 2400, meta: 600, msft: 434, wal: 0 });
  const [merCeiling, setMerCeiling] = useState(null);
  const [merDrag, setMerDrag] = useState(null); // visual-only during drag
  const [allocOpen, setAllocOpen] = useState(false);
  const [rampLeadIn, setRampLeadIn] = useState(7);
  const [rampMult, setRampMult] = useState(1.5);
  const [methodOpen, setMethodOpen] = useState(false);
  const [intelOpen, setIntelOpen] = useState(false);
  const [connectOpen, setConnectOpen] = useState(false);

  const actuals = useMemo(() => R.filter(has), []);
  const latest = actuals[actuals.length - 1];
  const last7 = actuals.slice(-7);
  const forecast = useMemo(() => buildForecast(actuals), [actuals]);
  const modelHealth = useMemo(() => trackModelHealth(actuals), [actuals]);
  const testPhase = useMemo(() => latest ? getTestPhase(latest[0]) : { phase: "idle" }, [latest]);
  const anomalies = useMemo(() => detectAnomalies(actuals), [actuals]);
  // MER ceiling auto-anchored to 14-day trailing actual MER (rounded up to nearest 0.5)
  const trailingMER = useMemo(() => {
    const rec = actuals.slice(-14);
    if (rec.length < 7) return 18;
    const sp = rec.reduce((s,r) => s + r[3], 0);
    const rv = rec.reduce((s,r) => s + r[2], 0);
    return rv > 0 ? Math.ceil(sp / rv * 100 * 2) / 2 : 18;
  }, [actuals]);
  const effectiveMerCeiling = merCeiling !== null ? merCeiling : trailingMER;

  const agg = useMemo(() => {
    const sum = (arr, i) => arr.reduce((s, r) => s + (r[i] || 0), 0);
    const avg = (arr, i) => arr.length > 0 ? sum(arr, i) / arr.length : 0;

    // Dynamic week: find most recent Sunday with actuals, then 7 days Mon-Sun
    const lastSun = [...actuals].reverse().find(r => r[1] === "Sun");
    const lastSunDate = lastSun ? lastSun[0] : "3/22";
    const sunIdx = R.findIndex(r => r[0] === lastSunDate);
    const wAll = sunIdx >= 6 ? R.slice(sunIdx - 6, sunIdx + 1) : R.slice(0, sunIdx + 1);
    const wAct = wAll.filter(has);
    const mAll = R.filter(r => r[0].startsWith("3/"));
    const mAct = mAll.filter(has);
    const qAct = actuals;

    function calc(arr, allArr) {
      return {
        rev: sum(arr, 2), spend: sum(arr, 3), mer: avg(arr, 4),
        revFc: sum(allArr || arr, 13), spFc: sum(allArr || arr, 14),
        revLy: sum(arr, 21), spLy: sum(arr, 22),
        rev24: sum(arr, 28), sp24: sum(arr, 29),
        days: arr.length
      };
    }

    return {
      weekly: calc(wAct, wAll), weeklyData: wAll,
      mtd: calc(mAct, mAll), mtdData: mAll,
      qtd: calc(qAct), qtdData: qAct,
      wStart: wAll.length > 0 ? wAll[0][0] : "", wEnd: wAll.length > 0 ? wAll[wAll.length-1][0] : "",
    };
  }, [actuals]);

  const toggle = (key) => setExpanded(expanded === key ? null : key);

  // Promo context for today
  const promoCtx = useMemo(() => getPromoContext(latest[0]), [latest]);
  const spendMult = useMemo(() => getSpendMultiplier(latest[0], rampLeadIn, rampMult), [latest, rampLeadIn, rampMult]);

  const projection = useMemo(() => {
    const b = budgets;
    const totalSp = b.amz + b.ggl + b.meta + b.msft + b.wal;
    const rev = projectRevenue(b.amz, b.ggl, b.meta, b.msft, b.wal);
    const c = projectContribution(b.amz, b.ggl, b.meta, b.msft, b.wal);
    const mer = totalSp > 0 ? (totalSp / rev.total * 100) : 0;
    const roas = totalSp > 0 ? rev.total / totalSp : 0;
    const amzRoas = b.amz > 0 ? rev.amz / b.amz : 0;
    const shopRoas = rev.nonAmzSp > 0 ? rev.shop / rev.nonAmzSp : 0;
    const fcRev = latest[13], fcSp = latest[14];
    return { totalSp, rev: rev.total, amzRev: rev.amz, shopRev: rev.shop, walRev: rev.wal, halo: rev.halo, mer, roas, amzRoas, shopRoas, revDelta: rev.total - fcRev, spDelta: totalSp - fcSp, fcRev, fcSp, contrib: c.grossContrib, ltvContrib: c.ltvContrib };
  }, [budgets, latest]);

  const decayCurve = useMemo(() => {
    const pts = [];
    for (let x = 6000; x <= 28000; x += 500) pts.push({ sp: x, roas: Math.round(AMZ_FIT.predict(x) / x * 10) / 10 });
    return pts;
  }, []);

  const amzScatter = useMemo(() => AMZ_SCATTER.map(d => ({ sp: d[0], roas: Math.round(d[1] / d[0] * 10) / 10 })), []);

  const setBudget = useCallback((ch, val) => setBudgets(prev => ({ ...prev, [ch]: val })), []);

  const rec = useMemo(() => {
    // CRITICAL: Use forecast daily spend as the base, NOT projection.totalSp
    // Otherwise clicking "Apply" feeds the inflated total back in and compounds
    const baseDailySpend = latest[14] || 17000;
    return recommendAllocation(baseDailySpend, effectiveMerCeiling, latest[13], spendMult.mult);
  }, [effectiveMerCeiling, latest, spendMult.mult]);
  const tableRef = useRef(null);
  const lastSunIdx = useMemo(() => {
    for (let i = R.length - 1; i >= 0; i--) { if (R[i][1] === "Sun" && has(R[i])) return i; }
    return 0;
  }, []);
  useEffect(() => {
    if (tableRef.current && chV === null) {
      const t = setTimeout(() => {
        const container = tableRef.current;
        const row = container && container.querySelector("[data-sun]");
        if (row && container) {
          container.scrollTop = row.offsetTop - container.offsetTop - 39;
        }
      }, 100);
      return () => clearTimeout(t);
    }
  }, [chV]);

  const css = `@import url('https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700;800&family=JetBrains+Mono:wght@400;500;600&display=swap');
  * { box-sizing: border-box; margin: 0; padding: 0; }
  ::-webkit-scrollbar { width: 5px; height: 5px; } ::-webkit-scrollbar-track { background: ${T.bg}; } ::-webkit-scrollbar-thumb { background: ${T.bd}; border-radius: 3px; }
  @keyframes fadeUp { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }
  .fi { animation: fadeUp .3s ease-out both; }
  .tbl { width: 100%; border-collapse: separate; border-spacing: 0; font-size: 11px; }
  .tbl th { position: sticky; z-index: 2; background: ${T.bg2}; padding: 4px 6px; text-align: right; font-weight: 600; color: ${T.t3}; font-size: 9px; text-transform: uppercase; letter-spacing: .3px; white-space: nowrap; }
  .tbl th.gh { top: 0; z-index: 4; font-size: 8px; letter-spacing: 1px; color: ${T.t4}; border-bottom: none; padding: 3px 6px; }
  .tbl th.sh { top: 17px; z-index: 3; border-bottom: 2px solid ${T.bd}; }
  .tbl th:first-child, .tbl th:nth-child(2), .tbl th:nth-child(3) { text-align: left; }
  .tbl td { padding: 3px 6px; text-align: right; border-bottom: 1px solid ${T.bd}; font-family: 'JetBrains Mono', monospace; font-size: 10.5px; white-space: nowrap; }
  .tbl td:first-child { text-align: left; font-weight: 600; color: ${T.tx}; font-family: 'Outfit', sans-serif; font-size: 11px; }
  .tbl td:nth-child(2), .tbl td:nth-child(3) { text-align: left; font-family: 'Outfit', sans-serif; }
  .tbl tr:hover td { background: ${T.cdH}; }
  @keyframes todayPulse { 0%,100% { background: rgba(245,158,11,.04); } 50% { background: rgba(245,158,11,.12); } }
  .tbl tr.today td { animation: todayPulse 3s ease-in-out infinite; }
  .sep { border-left: 1px solid ${T.bd}; }
  .acc { cursor: pointer; transition: all .15s; }
  .acc:hover { background: ${T.cdH} !important; }`;

  const d = latest;
  const revD = d[2] - d[13];
  const spD = d[3] - d[14];
  const totalChSpend = CN.reduce((s, _, i) => s + (d[CA[i]] || 0), 0);
  const totalChFc = CN.reduce((s, _, i) => s + (d[CF[i]] || 0), 0);
  const currentHour = 14; // 2:00 PM — will be dynamic with live feeds
  const revStatus = getPacingStatus(d[2], d[13], d[21], "revenue", currentHour);
  const spStatus = getPacingStatus(d[3], d[14], d[22], "spend", currentHour);

  const lastActDate = actuals.length > 0 ? actuals[actuals.length-1][0] : "3/22";
  const lastActDay = lastActDate.split("/")[1];
  const row2 = [
    { key: "weekly", label: "Weekly", sub: agg.wStart + " – " + agg.wEnd, color: T.cy, data: agg.weekly, chartData: agg.weeklyData },
    { key: "mtd", label: "MTD", sub: "Mar 1 – " + lastActDay, color: T.pu, data: agg.mtd, chartData: agg.mtdData },
    { key: "qtd", label: "QTD", sub: "Q1 • " + actuals.length + " days", color: T.gn, data: agg.qtd, chartData: agg.qtdData },
  ];

  return (
    <div style={{ background: T.bg, color: T.tx, minHeight: "100vh", fontFamily: "'Outfit', system-ui, sans-serif", fontSize: 13 }}>
      <style>{css}</style>

      <header style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "10px 20px", borderBottom: "1px solid " + T.bd, background: T.bg2, position: "sticky", top: 0, zIndex: 50 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <div style={{ width: 28, height: 28, borderRadius: 6, display: "flex", alignItems: "center", justifyContent: "center", background: "linear-gradient(135deg, " + T.ac + ", " + T.pu + ")", fontWeight: 800, fontSize: 12 }}>S</div>
          <div><div style={{ fontWeight: 700, fontSize: 14, letterSpacing: -.3 }}>SSM Command Center</div><div style={{ fontSize: 9, color: T.t3, letterSpacing: 1.5, textTransform: "uppercase" }}>Marketing Intelligence</div></div>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
          <span style={{ fontSize: 10, color: T.t3, fontFamily: "'JetBrains Mono', monospace" }}>Last actual: {actuals.length > 0 ? actuals[actuals.length-1][0] : "N/A"} | {actuals.length}d tracked | Q1 2026</span>
          <button onClick={() => setMethodOpen(!methodOpen)} style={{ padding: "4px 12px", borderRadius: 5, border: "1px solid " + (methodOpen ? T.cy : T.bd), background: methodOpen ? T.cy + "18" : "transparent", color: methodOpen ? T.cy : T.t3, fontSize: 10, fontWeight: 600, cursor: "pointer", fontFamily: "'Outfit', sans-serif" }}>
            {methodOpen ? "✕ Close" : "ℹ Methodology"}
          </button>
          {testPhase.phase !== "idle" && (
            <div style={{ display: "flex", alignItems: "center", gap: 5, padding: "4px 10px", borderRadius: 5, background: testPhase.phase === "testing" ? T.cy + "18" : testPhase.phase === "lag" ? T.am + "18" : T.gn + "18", border: "1px solid " + (testPhase.phase === "testing" ? T.cy : testPhase.phase === "lag" ? T.am : T.gn) + "40" }}>
              <div style={{ width: 5, height: 5, borderRadius: "50%", background: testPhase.phase === "testing" ? T.cy : testPhase.phase === "lag" ? T.am : T.gn }} />
              <span style={{ fontSize: 9, fontWeight: 600, color: testPhase.phase === "testing" ? T.cy : testPhase.phase === "lag" ? T.am : T.gn }}>
                {testPhase.ch} {testPhase.phase === "testing" ? "TEST DAY " + testPhase.day + "/" + testPhase.totalDays : testPhase.phase === "lag" ? "LAG DAY " + testPhase.day + "/7" : "WASHOUT DAY " + testPhase.day + "/7"}
              </span>
            </div>
          )}
          <button onClick={() => setIntelOpen(!intelOpen)} style={{ padding: "4px 12px", borderRadius: 5, border: "1px solid " + (intelOpen ? T.gn : T.bd), background: intelOpen ? T.gn + "18" : "transparent", color: intelOpen ? T.gn : T.t3, fontSize: 10, fontWeight: 600, cursor: "pointer", fontFamily: "'Outfit', sans-serif" }}>
            {intelOpen ? "✕ Close" : "◈ Intelligence"}
          </button>
          <button onClick={() => setConnectOpen(!connectOpen)} style={{ padding: "4px 12px", borderRadius: 5, border: "1px solid " + (connectOpen ? T.am : T.bd), background: connectOpen ? T.am + "18" : "transparent", color: connectOpen ? T.am : T.t3, fontSize: 10, fontWeight: 600, cursor: "pointer", fontFamily: "'Outfit', sans-serif" }}>
            {connectOpen ? "✕ Close" : "⚡ Connections " + API_CONNECTIONS.filter(a => a.status === "connected").length + "/" + API_CONNECTIONS.length}
          </button>
        </div>
      </header>

            {/* ═══ METHODOLOGY PANEL ═══ */}
      {methodOpen && (
        <div style={{ background: T.cd, borderBottom: "1px solid " + T.bd, padding: "20px 24px", maxHeight: "80vh", overflowY: "auto" }}>
          <div style={{ maxWidth: 1200, margin: "0 auto" }}>
            <div style={{ fontSize: 20, fontWeight: 800, marginBottom: 4 }}>System methodology</div>
            <div style={{ fontSize: 11, color: T.t3, marginBottom: 16 }}>SSM Marketing Command Center v6.0 — Technical Documentation</div>
            {[
              { t: "Revenue models", c: "Platform-decomposed power laws fitted on 764 days. Amazon: rev = " + AMZ_FIT.a.toFixed(1) + " × spend^" + AMZ_FIT.b.toFixed(2) + " (n=" + AMZ_FIT.n + "). Shopify: rev = " + SHOP_FIT.a.toFixed(1) + " × nonAmzSpend^" + SHOP_FIT.b.toFixed(2) + ". Meta halo: " + HALO_CEILING + " × (1 − e^(−spend/" + HALO_HALF + ")). Walmart: logistic saturation at $" + WAL_CEILING + " ceiling.", color: T.ac },
              { t: "Margin model", c: "Calibrated from 17,773 orders (Nov 2025 – Mar 2026). Amazon: 31.8% pre-ad (COGS 44.3%, fees 11.3%, ship 12.5%). Shopify: 42.2% pre-ad (COGS 42.9%, fees 4.2%, ship 10.8%). Walmart: 37.4%. Amazon orders under $300 are 47% negative margin — high-AOV targeting critical.", color: T.gn },
              { t: "Optimizer", c: "Gradient search (50 iterations) maximizing LTV-adjusted contribution margin under MER ceiling. Shifts $500 (Amz) or $100 (other) between channels per step. MER ceiling auto-set from 14-day trailing actuals. Relaxed 30% during promo ramp.", color: T.pu },
              { t: "Promo calendar", c: "13 events with baseline gaps. Lead-in/peak/lead-out phases. Spend multiplier from trend-weighted promo context. Ramp: Amazon 10-14d, Meta 7-10d, Google 5-7d. Self-correction if MER exceeds ceiling by 15% at day +4.", color: T.cy },
              { t: "Forecast engine", c: "Deseasonalized trend (30-day linear, DOW + promo stripped) × DOW coefficients (from all actuals) × spend elasticity (0.72 from power law). Responds to spend inputs.", color: T.am },
              { t: "Anomaly detection", c: "DOW-adjusted z-scores: each day compared to same-DOW from prior 8 weeks. Thresholds: warning at z-score below -1.5, critical below -2.0. Auto-classifies root cause: CVR collapse, spend under-delivery, MER spike, or organic decline.", color: T.rd },
              { t: "Data schema", c: "365 rows × 35 fields. Actuals through " + (latest ? latest[0] : "current") + ". Auto-scrolls to most recent Sunday. Promo indicators with 13 color-coded left borders.", color: T.t3 },
              { t: "API architecture", c: "10 external connections (Northbeam, Amazon, Google, Meta, Shopify, GA4, HubSpot, Microsoft, Keepa, Klaviyo). 3x daily cron cycle. See Connections panel for status.", color: T.rd },
            ].map((s, i) => (
              <div key={i} style={{ marginBottom: 8, padding: "8px 12px", background: T.bg, borderRadius: 6, border: "1px solid " + T.bd, borderLeft: "3px solid " + s.color }}>
                <span style={{ fontSize: 11, fontWeight: 700, color: s.color }}>{s.t}: </span>
                <span style={{ fontSize: 10, color: T.t2, lineHeight: 1.5 }}>{s.c}</span>
              </div>
            ))}
            <div style={{ fontSize: 10, color: T.t4, textAlign: "center", marginTop: 8 }}>Full technical details available in the Intelligence panel and API Specification document.</div>
          </div>
        </div>
      )}

{/* ═══ STRATEGIC INTELLIGENCE PANEL ═══ */}
      {intelOpen && (
        <div style={{ background: T.cd, borderBottom: "1px solid " + T.bd, padding: "20px 24px", maxHeight: "80vh", overflowY: "auto" }}>
          <div style={{ maxWidth: 1200, margin: "0 auto" }}>
            <div style={{ fontSize: 20, fontWeight: 800, marginBottom: 4 }}>Strategic intelligence</div>
            <div style={{ fontSize: 11, color: T.t3, marginBottom: 20 }}>Real-time diagnostics, forecasting, and optimization layers</div>

            {/* ═══ MODEL HEALTH + SELF-IMPROVEMENT ═══ */}
            <div style={{ marginBottom: 16, background: T.bg, borderRadius: 8, border: "1px solid " + T.bd, overflow: "hidden" }}>
              <div style={{ padding: "10px 14px", borderBottom: "1px solid " + T.bd, borderLeft: "3px solid " + (modelHealth && modelHealth.status === "healthy" ? T.gn : modelHealth && modelHealth.status === "drifting" ? T.am : T.rd) }}>
                <span style={{ fontSize: 13, fontWeight: 700, color: T.tx }}>Model health + auto-calibration</span>
                {modelHealth && <span style={{ fontSize: 9, marginLeft: 8, padding: "2px 6px", borderRadius: 3, background: (modelHealth.status === "healthy" ? T.gn : modelHealth.status === "drifting" ? T.am : T.rd) + "20", color: modelHealth.status === "healthy" ? T.gn : modelHealth.status === "drifting" ? T.am : T.rd, fontWeight: 600 }}>{modelHealth.status.toUpperCase()} • MAPE {modelHealth.mape.toFixed(1)}%</span>}
              </div>
              <div style={{ padding: "10px 14px" }}>
                {modelHealth ? (
                  <div>
                    <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr 1fr", gap: 10, marginBottom: 10 }}>
                      {[
                        { label: "14-day MAPE", val: modelHealth.mape.toFixed(1) + "%", sub: "Mean absolute prediction error", color: modelHealth.mape < 15 ? T.gn : modelHealth.mape < 25 ? T.am : T.rd },
                        { label: "Model bias", val: (modelHealth.bias >= 0 ? "+" : "") + modelHealth.bias.toFixed(1) + "%", sub: modelHealth.bias > 0 ? "Over-predicting" : "Under-predicting", color: Math.abs(modelHealth.bias) < 10 ? T.gn : T.am },
                        { label: "Amazon refit R²", val: modelHealth.amzRefit ? modelHealth.amzRefit.r2.toFixed(3) : "—", sub: modelHealth.amzRefit ? "n=" + modelHealth.amzRefit.n + " days" : "", color: modelHealth.amzRefit && modelHealth.amzRefit.r2 > 0.5 ? T.gn : T.am },
                        { label: "Shopify refit R²", val: modelHealth.shopRefit ? modelHealth.shopRefit.r2.toFixed(3) : "—", sub: modelHealth.shopRefit ? "n=" + modelHealth.shopRefit.n + " days" : "", color: modelHealth.shopRefit && modelHealth.shopRefit.r2 > 0.3 ? T.gn : T.am },
                      ].map((m, i) => (
                        <div key={i} style={{ padding: "8px 10px", background: T.cd, borderRadius: 6, border: "1px solid " + T.bd }}>
                          <div style={{ fontSize: 9, color: T.t3, textTransform: "uppercase", letterSpacing: .5 }}>{m.label}</div>
                          <div style={{ fontSize: 18, fontWeight: 800, color: m.color, marginTop: 2 }}>{m.val}</div>
                          <div style={{ fontSize: 9, color: T.t4, marginTop: 2 }}>{m.sub}</div>
                        </div>
                      ))}
                    </div>
                    {modelHealth.amzRefit && modelHealth.amzDrift && (
                      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 10 }}>
                        <div style={{ padding: "8px 10px", background: T.cd, borderRadius: 6, border: "1px solid " + T.bd }}>
                          <div style={{ fontSize: 10, fontWeight: 700, color: T.t2, marginBottom: 4 }}>Amazon power law drift</div>
                          <div style={{ fontSize: 10, color: T.t3 }}>
                            Static: a={AMZ_FIT.a.toFixed(2)}, b={AMZ_FIT.b.toFixed(4)} (n={AMZ_FIT.n})
                          </div>
                          <div style={{ fontSize: 10, color: Math.abs(modelHealth.amzDrift.b) < 5 ? T.gn : T.am }}>
                            Refit: a={modelHealth.amzRefit.a.toFixed(2)}, b={modelHealth.amzRefit.b.toFixed(4)} (n={modelHealth.amzRefit.n})
                          </div>
                          <div style={{ fontSize: 9, color: T.t4, marginTop: 2 }}>
                            Drift: a={modelHealth.amzDrift.a >= 0 ? "+" : ""}{modelHealth.amzDrift.a.toFixed(1)}%, b={modelHealth.amzDrift.b >= 0 ? "+" : ""}{modelHealth.amzDrift.b.toFixed(1)}%
                          </div>
                        </div>
                        <div style={{ padding: "8px 10px", background: T.cd, borderRadius: 6, border: "1px solid " + T.bd }}>
                          <div style={{ fontSize: 10, fontWeight: 700, color: T.t2, marginBottom: 4 }}>Shopify power law drift</div>
                          <div style={{ fontSize: 10, color: T.t3 }}>
                            Static: a={SHOP_FIT.a.toFixed(2)}, b={SHOP_FIT.b.toFixed(4)} (n={SHOP_FIT.n})
                          </div>
                          {modelHealth.shopRefit && <div style={{ fontSize: 10, color: Math.abs(modelHealth.shopDrift.b) < 10 ? T.gn : T.am }}>
                            Refit: a={modelHealth.shopRefit.a.toFixed(2)}, b={modelHealth.shopRefit.b.toFixed(4)} (n={modelHealth.shopRefit.n})
                          </div>}
                          {modelHealth.shopDrift && <div style={{ fontSize: 9, color: T.t4, marginTop: 2 }}>
                            Drift: a={modelHealth.shopDrift.a >= 0 ? "+" : ""}{modelHealth.shopDrift.a.toFixed(1)}%, b={modelHealth.shopDrift.b >= 0 ? "+" : ""}{modelHealth.shopDrift.b.toFixed(1)}%
                          </div>}
                        </div>
                      </div>
                    )}
                    <div style={{ fontSize: 11, color: T.t2, lineHeight: 1.6 }}>
                      Auto-refits on every data load. Flags when MAPE {'>'}25% or drift {'>'}15%. Geo-lift results override model coefficients with measured data.
                    </div>
                  </div>
                ) : <div style={{ fontSize: 11, color: T.t3 }}>Need 30+ days of actuals for model health tracking</div>}
              </div>
            </div>

            {/* ═══ ANOMALY DETECTION ═══ */}
            <div style={{ marginBottom: 16, background: T.bg, borderRadius: 8, border: "1px solid " + T.bd, overflow: "hidden" }}>
              <div style={{ padding: "10px 14px", borderBottom: "1px solid " + T.bd, borderLeft: "3px solid " + T.rd }}>
                <span style={{ fontSize: 13, fontWeight: 700, color: T.rd }}>Anomaly detection (last 7 days)</span>
              </div>
              <div style={{ padding: "10px 14px" }}>
                {anomalies.length === 0 ? (
                  <div style={{ fontSize: 11, color: T.gn }}>✓ No anomalies detected — all metrics within expected bands</div>
                ) : anomalies.map((a, i) => (
                  <div key={i} style={{ fontSize: 11, color: a.sev === "critical" ? T.rd : a.sev === "warning" ? T.am : T.cy, marginBottom: 6, padding: "6px 8px", background: (a.sev === "critical" ? T.rd : a.sev === "warning" ? T.am : T.cy) + "10", borderRadius: 4 }}>
                    <span style={{ fontWeight: 700 }}>{a.date}</span> — {a.sev.toUpperCase()} (z={a.z}) — Expected {fm(a.exp)}, got {fm(a.act)}
                    <div style={{ color: T.t2, marginTop: 2 }}>Root cause: {a.cause}</div>
                  </div>
                ))}
              </div>
            </div>

            {/* ═══ CONTRIBUTION MARGIN ═══ */}
            <div style={{ marginBottom: 16, background: T.bg, borderRadius: 8, border: "1px solid " + T.bd, overflow: "hidden" }}>
              <div style={{ padding: "10px 14px", borderBottom: "1px solid " + T.bd, borderLeft: "3px solid " + T.gn }}>
                <span style={{ fontSize: 13, fontWeight: 700, color: T.gn }}>Contribution margin model</span>
              </div>
              <div style={{ padding: "10px 14px" }}>
                {(() => {
                  const c = projectContribution(budgets.amz, budgets.ggl, budgets.meta, budgets.msft, budgets.wal);
                  return (
                    <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr 1fr", gap: 10 }}>
                      {[
                        { label: "Amazon contribution", val: c.amzContrib, sub: "Rev " + fm(c.amz) + " × 35.1% pre-ad margin − spend" },
                        { label: "Shopify contribution", val: c.shopContrib, sub: "Rev " + fm(c.shop) + " × 34.7% pre-ad margin (Sven) − spend" },
                        { label: "Gross contribution", val: c.grossContrib, sub: "Revenue margin minus all ad spend" },
                        { label: "LTV-adjusted contribution", val: c.ltvContrib, sub: "Weighted by " + (MARGIN.newCustPremium) + "x new customer LTV" },
                      ].map((m, i) => (
                        <div key={i} style={{ padding: "8px 10px", background: T.cd, borderRadius: 6, border: "1px solid " + T.bd }}>
                          <div style={{ fontSize: 9, color: T.t3, textTransform: "uppercase", letterSpacing: .5 }}>{m.label}</div>
                          <div style={{ fontSize: 18, fontWeight: 800, color: m.val >= 0 ? T.gn : T.rd, marginTop: 2 }}>{fm(m.val)}</div>
                          <div style={{ fontSize: 9, color: T.t4, marginTop: 2 }}>{m.sub}</div>
                        </div>
                      ))}
                    </div>
                  );
                })()}
                <div style={{ fontSize: 11, color: T.t2, marginTop: 10, lineHeight: 1.6 }}>
                  The optimizer maximizes LTV-adjusted contribution margin using 764-day power-law fits calibrated against 17,773 orders of real margin data. Amazon pre-ad margin is 31.8% of net sales (COGS 44.3%, fees 11.3%, shipping 12.5%). Shopify pre-ad margin is 42.2% (COGS 42.9%, fees 4.2%, shipping 10.8%). The 10-point gap means Shopify revenue is more valuable per dollar, but Amazon's higher volume and the Meta halo effect (which flows through Amazon's margin) keep Amazon as the primary budget target. Critical finding: 47% of Amazon orders under $300 are negative margin — ad targeting should shift toward high-AOV products ($800+) where contribution margin is 33.5%. Geekz Shopify is excluded: -$161K contribution on $74K net sales.
                </div>
              </div>
            </div>

            <div style={{ fontSize: 10, color: T.t4, textAlign: "center", padding: "8px 0" }}>
              Strategic Intelligence Layer v1.0 — Model Health • Anomaly Detection • Contribution Margin
            </div>
          </div>
        </div>
      )}

      {/* ═══ API CONNECTIONS PANEL ═══ */}
      {connectOpen && (
        <div style={{ background: T.cd, borderBottom: "1px solid " + T.bd, padding: "20px 24px", maxHeight: "80vh", overflowY: "auto" }}>
          <div style={{ maxWidth: 1200, margin: "0 auto" }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 4 }}>
              <div style={{ fontSize: 20, fontWeight: 800 }}>API connections</div>
              <div style={{ display: "flex", gap: 8, fontSize: 10 }}>
                <span style={{ color: T.gn }}>● {API_CONNECTIONS.filter(a => a.status === "connected").length} connected</span>
                <span style={{ color: T.t3 }}>● {API_CONNECTIONS.filter(a => a.status === "not_connected").length} pending</span>
              </div>
            </div>
            <div style={{ fontSize: 11, color: T.t3, marginBottom: 20 }}>Manage data source connections. Priority order reflects implementation roadmap.</div>

            {/* Status overview */}
            <div style={{ padding: "14px 16px", background: T.bg, borderRadius: 10, border: "1px solid " + T.bd, marginBottom: 20 }}>
              <div style={{ display: "grid", gridTemplateColumns: "repeat(" + API_CONNECTIONS.length + ", 1fr)", gap: 4 }}>
                {API_CONNECTIONS.map((api, i) => {
                  const sc = api.status === "connected" ? T.gn : api.status === "error" ? T.rd : api.status === "degraded" ? T.am : T.t4;
                  const m = api.metrics;
                  return (
                    <div key={i} style={{ textAlign: "center" }}>
                      <div style={{ height: 8, borderRadius: 4, background: sc + (api.status === "connected" ? "" : "40"), marginBottom: 6, transition: "background .3s" }} />
                      <div style={{ fontSize: 8, fontWeight: 600, color: sc, lineHeight: 1.2, letterSpacing: .2 }}>{api.name.replace(" Marketing", "").replace(" Admin", "")}</div>
                      <div style={{ fontSize: 7, color: T.t4, marginTop: 1 }}>{api.dataFlow === "push+pull" ? "↕ push+pull" : api.dataFlow === "pull" ? "↓ pull" : "↑ push"}</div>
                      {m.lastSync && <div style={{ fontSize: 6, color: T.t3, marginTop: 1 }}>{m.lastSync.split(" ")[0]}</div>}
                      {m.uptime !== null && <div style={{ fontSize: 6, color: m.uptime >= 99 ? T.gn : m.uptime >= 95 ? T.am : T.rd, marginTop: 1 }}>{m.uptime}% uptime</div>}
                    </div>
                  );
                })}
              </div>
              {/* Aggregate stats */}
              {(() => {
                const connected = API_CONNECTIONS.filter(a => a.status === "connected");
                const totalSyncs = connected.reduce((s, a) => s + a.metrics.totalSyncs, 0);
                const avgUp = connected.length > 0 ? connected.reduce((s, a) => s + (a.metrics.uptime || 0), 0) / connected.length : 0;
                const lastErr = API_CONNECTIONS.filter(a => a.metrics.lastError).sort((a, b) => b.metrics.lastError > a.metrics.lastError ? 1 : -1)[0];
                return connected.length > 0 ? (
                  <div style={{ display: "flex", justifyContent: "center", gap: 16, marginTop: 10, paddingTop: 8, borderTop: "1px solid " + T.bd, fontSize: 9 }}>
                    <span style={{ color: T.t3 }}>{totalSyncs} total syncs</span>
                    <span style={{ color: avgUp >= 99 ? T.gn : T.am }}>{avgUp.toFixed(1)}% avg uptime</span>
                    {lastErr && <span style={{ color: T.t4 }}>Last error: {lastErr.name} {lastErr.metrics.lastError.split(" ")[0]}</span>}
                  </div>
                ) : null;
              })()}
            </div>

            {/* API status grid */}
            <div style={{ display: "grid", gridTemplateColumns: "repeat(2, 1fr)", gap: 8 }}>
              {API_CONNECTIONS.map((api, i) => {
                const sc = api.status === "connected" ? T.gn : api.status === "error" ? T.rd : api.status === "degraded" ? T.am : T.t4;
                const sl = { connected: "Connected", not_connected: "Not connected", error: "Error", degraded: "Degraded" };
                const m = api.metrics;
                const hasMetrics = m.totalSyncs > 0;
                return (
                  <div key={i} style={{ background: T.bg, borderRadius: 8, border: "1px solid " + T.bd, borderLeft: "3px solid " + sc, overflow: "hidden" }}>
                    {/* Header */}
                    <div style={{ padding: "8px 10px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                      <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                        <span style={{ fontSize: 12, fontWeight: 700, color: T.tx }}>{api.name}</span>
                        <span style={{ fontSize: 7, padding: "1px 5px", borderRadius: 3, background: sc + "18", color: sc, fontWeight: 600 }}>{sl[api.status]}</span>
                      </div>
                      <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                        <span style={{ fontSize: 8, color: T.t4 }}>P{api.priority}</span>
                        <span style={{ fontSize: 8, padding: "1px 5px", borderRadius: 3, background: T.cd, color: T.t3 }}>{api.authType.split(" ")[0]}</span>
                      </div>
                    </div>

                    {/* Purpose + endpoint */}
                    <div style={{ padding: "0 10px 6px", fontSize: 9, color: T.t3, lineHeight: 1.4 }}>
                      {api.purpose.substring(0, 80)}{api.purpose.length > 80 ? "..." : ""}
                    </div>

                    {/* Metrics row */}
                    <div style={{ display: "grid", gridTemplateColumns: hasMetrics ? "1fr 1fr 1fr 1fr 1fr" : "1fr 1fr 1fr", gap: 0, borderTop: "1px solid " + T.bd, background: T.cd }}>
                      {/* Last sync */}
                      <div style={{ padding: "5px 8px", borderRight: "1px solid " + T.bd }}>
                        <div style={{ fontSize: 7, color: T.t4, textTransform: "uppercase", letterSpacing: .3 }}>Last sync</div>
                        <div style={{ fontSize: 10, fontWeight: 600, fontFamily: "'JetBrains Mono', monospace", color: m.lastSync ? T.tx : T.t4, marginTop: 1 }}>{m.lastSync || "—"}</div>
                      </div>

                      {/* Frequency + direction */}
                      <div style={{ padding: "5px 8px", borderRight: "1px solid " + T.bd }}>
                        <div style={{ fontSize: 7, color: T.t4, textTransform: "uppercase", letterSpacing: .3 }}>Schedule</div>
                        <div style={{ fontSize: 10, fontWeight: 600, color: T.t2, marginTop: 1 }}>{api.frequency}</div>
                        <div style={{ fontSize: 7, color: T.t4 }}>{api.dataFlow === "push+pull" ? "↕ push + pull" : api.dataFlow === "pull" ? "↓ pull only" : "↑ push only"}</div>
                      </div>

                      {/* Errors */}
                      <div style={{ padding: "5px 8px", borderRight: hasMetrics ? "1px solid " + T.bd : "none" }}>
                        <div style={{ fontSize: 7, color: T.t4, textTransform: "uppercase", letterSpacing: .3 }}>Errors</div>
                        {m.lastError ? (
                          <div>
                            <div style={{ fontSize: 10, fontWeight: 600, color: T.rd, marginTop: 1 }}>{m.errorCount > 0 ? m.errorCount + " consecutive" : "Last: " + m.lastError.split(" ")[0]}</div>
                          </div>
                        ) : (
                          <div style={{ fontSize: 10, fontWeight: 600, color: hasMetrics ? T.gn : T.t4, marginTop: 1 }}>{hasMetrics ? "None" : "—"}</div>
                        )}
                      </div>

                      {/* Connected-only metrics */}
                      {hasMetrics && (
                        <div style={{ padding: "5px 8px", borderRight: "1px solid " + T.bd }}>
                          <div style={{ fontSize: 7, color: T.t4, textTransform: "uppercase", letterSpacing: .3 }}>Performance</div>
                          <div style={{ fontSize: 10, fontWeight: 600, color: T.t2, marginTop: 1 }}>{m.avgLatency}ms avg</div>
                          <div style={{ fontSize: 7, color: T.t4 }}>{m.totalSyncs} total syncs</div>
                        </div>
                      )}

                      {hasMetrics && (
                        <div style={{ padding: "5px 8px" }}>
                          <div style={{ fontSize: 7, color: T.t4, textTransform: "uppercase", letterSpacing: .3 }}>Health</div>
                          <div style={{ display: "flex", alignItems: "center", gap: 4, marginTop: 1 }}>
                            <div style={{ width: 36, height: 4, borderRadius: 2, background: T.bd, overflow: "hidden" }}>
                              <div style={{ width: m.uptime + "%", height: "100%", background: m.uptime >= 99 ? T.gn : m.uptime >= 95 ? T.am : T.rd, borderRadius: 2 }} />
                            </div>
                            <span style={{ fontSize: 10, fontWeight: 600, color: m.uptime >= 99 ? T.gn : m.uptime >= 95 ? T.am : T.rd }}>{m.uptime}%</span>
                          </div>
                          <div style={{ fontSize: 7, color: T.t4 }}>{m.recordsLast ? m.recordsLast.toLocaleString() + " records last" : ""}</div>
                        </div>
                      )}
                    </div>

                    {/* Action footer */}
                    <div style={{ padding: "4px 10px", borderTop: "1px solid " + T.bd, display: "flex", justifyContent: "space-between", alignItems: "center", background: T.bg }}>
                      <span style={{ fontSize: 8, color: T.t4, fontFamily: "'JetBrains Mono', monospace" }}>{api.endpoint.substring(0, 40)}</span>
                      <div style={{ display: "flex", gap: 4 }}>
                        {api.status === "connected" && (
                          <>
                            <span style={{ fontSize: 8, padding: "2px 8px", borderRadius: 3, background: T.cd, color: T.t3, cursor: "pointer", border: "1px solid " + T.bd }}>Test</span>
                            <span style={{ fontSize: 8, padding: "2px 8px", borderRadius: 3, background: T.cd, color: T.t3, cursor: "pointer", border: "1px solid " + T.bd }}>Logs</span>
                            <span style={{ fontSize: 8, padding: "2px 8px", borderRadius: 3, background: T.cd, color: T.t3, cursor: "pointer", border: "1px solid " + T.bd }}>Sync now</span>
                          </>
                        )}
                        {api.status !== "connected" && (
                          <span style={{ fontSize: 8, padding: "2px 8px", borderRadius: 3, background: T.am + "18", color: T.am, fontWeight: 600, cursor: "pointer", border: "1px solid " + T.am + "30" }}>Configure</span>
                        )}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
</div>
        </div>
      )}

      <div style={{ padding: "16px 20px", maxWidth: 1800, margin: "0 auto" }}>

        {/* ═══ ROW 1: DAILY BRIEFING — single day pacing ═══ */}
        {chV === null && (
          <div className="fi" style={{ background: "linear-gradient(135deg, " + T.cd + " 0%, " + T.bg2 + " 100%)", border: "1px solid " + T.bd, borderRadius: 14, padding: 20, marginBottom: 14, borderTop: "3px solid " + T.ac }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                <div>
                  <div style={{ fontSize: 10, color: T.t3, textTransform: "uppercase", letterSpacing: 1.2, fontWeight: 600 }}>Today | Monday, March 16, 2026</div>
                  <div style={{ fontSize: 20, fontWeight: 800, letterSpacing: -.5 }}>Daily Briefing</div>
                </div>
                <div style={{ display: "flex", alignItems: "center", gap: 5, padding: "3px 10px", borderRadius: 5, background: T.am + "15", border: "1px solid " + T.am + "30" }}>
                  <div style={{ width: 6, height: 6, borderRadius: "50%", background: T.am }} />
                  <span style={{ fontSize: 9, color: T.am, fontWeight: 600 }}>AWAITING LIVE FEEDS</span>
                </div>
                {promoCtx.promo && (
                  <div style={{ display: "flex", alignItems: "center", gap: 5, padding: "3px 10px", borderRadius: 5, background: T.cy + "15", border: "1px solid " + T.cy + "30" }}>
                    <div style={{ width: 6, height: 6, borderRadius: "50%", background: T.cy }} />
                    <span style={{ fontSize: 9, color: T.cy, fontWeight: 600 }}>{promoCtx.promo}</span>
                    <span style={{ fontSize: 8, color: T.t3, textTransform: "uppercase" }}>{promoCtx.phase}</span>
                    {spendMult.mult > 1.02 && <span style={{ fontSize: 8, fontFamily: "'JetBrains Mono', monospace", color: T.am, fontWeight: 600 }}>{spendMult.mult.toFixed(2)}x</span>}
                  </div>
                )}
                {anomalies.length > 0 && (
                  <div style={{ display: "flex", alignItems: "center", gap: 5, padding: "3px 10px", borderRadius: 5, background: T.rd + "15", border: "1px solid " + T.rd + "30", cursor: "pointer" }} onClick={() => setIntelOpen(true)}>
                    <div style={{ width: 6, height: 6, borderRadius: "50%", background: T.rd }} />
                    <span style={{ fontSize: 9, color: T.rd, fontWeight: 600 }}>{anomalies.filter(a => a.sev === "critical").length > 0 ? "CRITICAL" : "WARNING"}: {anomalies.length} anomal{anomalies.length === 1 ? "y" : "ies"}</span>
                  </div>
                )}
              </div>
              <div style={{ display: "flex", gap: 16, fontSize: 10, color: T.t3 }}>
                <span>2025 match: <b style={{ color: T.t2 }}>{d[20]}/2025</b></span>
                <span>2024 match: <b style={{ color: T.t2 }}>{d[27]}/2024</b></span>
              </div>
            </div>

            {/* Spend + Revenue pacing */}
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14, marginBottom: 14 }}>
              {[
                { label: "Spend", stat: spStatus, actual: d[3], forecast: d[14], ly: d[22], lyDate: d[20], color: T.ac },
                { label: "Revenue", stat: revStatus, actual: d[2], forecast: d[13], ly: d[21], lyDate: d[20], color: T.gn }
              ].map((p, pi) => {
                const isSpend = pi === 0;
                const actualOfDay = p.forecast > 0 ? Math.round(p.actual / p.forecast * 100) : 0;
                const delta = p.actual - p.stat.expectedNow;
                const eodDelta = p.stat.eodProjected - p.forecast;
                const maxVal = Math.max(p.forecast, p.stat.eodProjected, p.ly, p.actual) * 1.05;
                const bar = (val, c, lbl, sublabel) => (
                  <div style={{ marginBottom: 6 }}>
                    <div style={{ display: "flex", justifyContent: "space-between", fontSize: 9, marginBottom: 2 }}>
                      <span style={{ color: T.t3 }}>{lbl}</span>
                      <span style={{ fontWeight: 600, fontFamily: "'JetBrains Mono', monospace", color: c }}>{fc(val)}{sublabel ? <span style={{ color: T.t4, fontWeight: 400 }}> {sublabel}</span> : null}</span>
                    </div>
                    <div style={{ height: 6, background: T.cd, borderRadius: 3, overflow: "hidden" }}>
                      <div style={{ height: "100%", width: (maxVal > 0 ? val / maxVal * 100 : 0) + "%", background: c, borderRadius: 3, transition: "width .3s" }} />
                    </div>
                  </div>
                );
                return (
                  <div key={pi} style={{ background: T.bg, borderRadius: 10, padding: 16, border: "1px solid " + T.bd }}>
                    {/* Header */}
                    <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 12 }}>
                      <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                        <span style={{ fontSize: 10, color: T.t3, textTransform: "uppercase", letterSpacing: .8, fontWeight: 600 }}>{p.label}</span>
                        <StatusBadge s={p.stat} />
                      </div>
                      <span style={{ fontSize: 10, color: T.t3, fontFamily: "'JetBrains Mono', monospace" }}>{currentHour}:00</span>
                    </div>

                    {/* Hero number */}
                    <div style={{ marginBottom: 14 }}>
                      <div style={{ fontSize: 34, fontWeight: 800, fontFamily: "'JetBrains Mono', monospace", color: p.color, lineHeight: 1 }}>{fm(p.actual)}</div>
                      <div style={{ fontSize: 10, color: T.t4, marginTop: 3 }}>so far today — <span style={{ color: delta >= 0 ? (isSpend ? T.am : T.gn) : (isSpend ? T.gn : T.am), fontWeight: 600 }}>{delta >= 0 ? "+" : ""}{fc(delta)}</span> vs expected at {currentHour}:00</div>
                    </div>

                    {/* Comparative bars */}
                    {bar(p.actual, p.color, "Actual (so far)", actualOfDay + "%")}
                    {bar(p.stat.eodProjected, p.stat.color, "EOD projection", (eodDelta >= 0 ? "+" : "") + fc(eodDelta) + " vs fc")}
                    {bar(p.forecast, T.am, "Forecast", null)}
                    {bar(p.ly, "#8a919c", "LY (" + p.lyDate + ")", pc(p.ly > 0 ? (p.actual - p.ly) / p.ly * 100 : 0) + " YoY")}

                    <InsightPanel insights={p.stat.insights} color={p.stat.color} hourlyLog={p.stat.hourlyLog} misses={p.stat.misses} />
                  </div>
                );
              })}
            </div>

            {/* Row 2: Efficiency + Channel Spend Pie + Rev by Marketplace Pie */}
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 14 }}>
              {/* Efficiency Metrics */}
              <div style={{ background: T.bg, borderRadius: 10, padding: 14, border: "1px solid " + T.bd }}>
                <div style={{ fontSize: 9, color: T.t3, textTransform: "uppercase", letterSpacing: .6, fontWeight: 600, marginBottom: 8 }}>Efficiency metrics</div>
                {(() => {
                  const mer = d[3] > 0 && d[2] > 0 ? (d[3] / d[2] * 100) : 0;
                  const acos = d[8] > 0 && d[5] > 0 ? (d[8] / d[5] * 100) : 0;
                  const roas = d[3] > 0 ? (d[2] / d[3]) : 0;
                  const tacos = d[8] > 0 && d[5] > 0 ? (d[8] / d[5] * 100) : 0;
                  const merLY = d[26] || 0;
                  const metrics = [
                    { n: "MER", v: mer.toFixed(1) + "%", sub: "Total spend / total rev", c: mer > 20 ? T.rd : mer > 16 ? T.am : T.gn, ly: merLY > 0 ? merLY + "%" : null },
                    { n: "ROAS", v: roas.toFixed(2) + "x", sub: "Total rev / total spend", c: roas > 6 ? T.gn : roas > 4 ? T.am : T.rd, ly: merLY > 0 ? (100/merLY).toFixed(2) + "x" : null },
                    { n: "Amazon ACOS", v: acos.toFixed(1) + "%", sub: "Amazon spend / Amazon paid rev", c: acos > 25 ? T.rd : acos > 18 ? T.am : T.gn, ly: null },
                    { n: "Amazon TACoS", v: tacos.toFixed(1) + "%", sub: "Amazon spend / Amazon paid + organic rev", c: tacos > 30 ? T.rd : tacos > 22 ? T.am : T.gn, ly: null },
                    { n: "Google ROAS", v: "—", sub: "Google rev / Google spend", c: T.t3, ly: null, api: "Google Ads" },
                    { n: "Meta ROAS", v: "—", sub: "Meta rev / Meta spend", c: T.t3, ly: null, api: "Meta Ads" },
                  ];
                  return (
                    <div>
                      {metrics.map((m, i) => (
                        <div key={i} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "5px 0", borderBottom: i < metrics.length - 1 ? "1px solid " + T.bd : "none" }}>
                          <div>
                            <div style={{ fontSize: 11, fontWeight: 600, color: m.api ? T.t3 : T.tx }}>{m.n}</div>
                            <div style={{ fontSize: 8, color: T.t4 }}>{m.sub}</div>
                          </div>
                          <div style={{ textAlign: "right" }}>
                            {m.api ? (
                              <div style={{ fontSize: 9, color: T.t4, fontStyle: "italic" }}>Needs {m.api} API</div>
                            ) : (
                              <div style={{ fontSize: 16, fontWeight: 700, fontFamily: "'JetBrains Mono', monospace", color: m.c }}>{m.v}</div>
                            )}
                            {m.ly && <div style={{ fontSize: 8, color: T.pu }}>LY: {m.ly}</div>}
                          </div>
                        </div>
                      ))}
                    </div>
                  );
                })()}
              </div>

              {/* Channel Spend — Dual Ring Pie */}
              <div style={{ background: T.bg, borderRadius: 10, padding: 14, border: "1px solid " + T.bd }}>
                <div style={{ fontSize: 9, color: T.t3, textTransform: "uppercase", letterSpacing: .6, fontWeight: 600, marginBottom: 4 }}>Channel spend vs forecast</div>
                <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                  <div style={{ width: "55%" }}>
                    <DualRingPie id="chsp" outerData={CN.map((ch, i) => ({ name: ch, value: d[CF[i]] || 1 }))} innerData={CN.map((ch, i) => ({ name: ch, value: d[CA[i]] || 0 }))} outerColors={CC} innerColors={CC} height={200} />
                  </div>
                  <div style={{ flex: 1 }}>
                    {CN.map((ch, i) => {
                      const a = d[CA[i]] || 0;
                      const f = d[CF[i]] || 0;
                      const delta = a - f;
                      return (
                        <div key={i} style={{ display: "flex", alignItems: "center", gap: 4, padding: "2px 0", borderBottom: i < CN.length - 1 ? "1px solid " + T.bd : "none" }}>
                          <div style={{ width: 6, height: 6, borderRadius: 1, background: CC[i], flexShrink: 0 }} />
                          <span style={{ fontSize: 8, color: T.t3, flex: 1 }}>{ch}</span>
                          <span style={{ fontSize: 9, fontWeight: 600, fontFamily: "'JetBrains Mono', monospace", color: delta > 0 ? T.rd : delta < 0 ? T.gn : T.t3 }}>
                            {delta !== 0 ? (delta > 0 ? "+" : "−") + fm(Math.abs(delta)) : "—"}
                          </span>
                        </div>
                      );
                    })}
                    <div style={{ marginTop: 4, padding: "3px 0", borderTop: "1px solid " + T.bd }}>
                      <div style={{ display: "flex", justifyContent: "space-between", fontSize: 8, color: T.t3 }}>
                        <span>Fc: <span style={{ color: T.am, fontFamily: "'JetBrains Mono', monospace" }}>{fm(totalChFc)}</span></span>
                        <span>Act: <span style={{ color: T.ac, fontFamily: "'JetBrains Mono', monospace" }}>{fm(totalChSpend)}</span></span>
                      </div>
                    </div>
                  </div>
                </div>
                {/* Forecast adherence scores */}
                {(() => {
                  const delivPct = totalChFc > 0 ? (totalChSpend / totalChFc * 100) : 0;
                  const actShares = CN.map((_, i) => totalChSpend > 0 ? (d[CA[i]] || 0) / totalChSpend : 0);
                  const fcShares = CN.map((_, i) => totalChFc > 0 ? (d[CF[i]] || 0) / totalChFc : 0);
                  const mixDrift = actShares.reduce((s, a, i) => s + Math.abs(a - fcShares[i]), 0) / 2 * 100;
                  const mixScore = Math.round(100 - mixDrift);
                  const delivColor = delivPct > 115 ? T.rd : delivPct > 105 ? T.am : delivPct >= 90 ? T.gn : T.am;
                  const mixColor = mixScore >= 90 ? T.gn : mixScore >= 75 ? T.am : T.rd;
                  return (
                    <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
                      <div style={{ flex: 1, textAlign: "center", padding: "6px 4px", borderRadius: 6, background: T.cd, border: "1px solid " + T.bd }}>
                        <div style={{ fontSize: 8, color: T.t3, marginBottom: 2 }}>Delivery vs plan</div>
                        <div style={{ fontSize: 16, fontWeight: 700, fontFamily: "'JetBrains Mono', monospace", color: delivColor }}>{Math.round(delivPct)}%</div>
                      </div>
                      <div style={{ flex: 1, textAlign: "center", padding: "6px 4px", borderRadius: 6, background: T.cd, border: "1px solid " + T.bd }}>
                        <div style={{ fontSize: 8, color: T.t3, marginBottom: 2 }}>Mix accuracy</div>
                        <div style={{ fontSize: 16, fontWeight: 700, fontFamily: "'JetBrains Mono', monospace", color: mixColor }}>{mixScore}%</div>
                      </div>
                    </div>
                  );
                })()}
              </div>

              {/* Revenue by Marketplace — Dual Ring Pie */}
              <div style={{ background: T.bg, borderRadius: 10, padding: 14, border: "1px solid " + T.bd }}>
                <div style={{ fontSize: 9, color: T.t3, textTransform: "uppercase", letterSpacing: .6, fontWeight: 600, marginBottom: 4 }}>Revenue by marketplace</div>
                {(() => {
                  const mktData = [
                    { n: "Amazon", v: d[5], c: "#FF9900" },
                    { n: "Shopify Online", v: Math.round(d[6] * 0.65), c: "#95BF47" },
                    { n: "Shopify Draft", v: Math.round(d[6] * 0.35), c: "#6B8E23" },
                    { n: "Walmart", v: d[7], c: "#0071DC" },
                  ];
                  const mktColors = mktData.map(m => m.c);
                  const totalActRev = mktData.reduce((s, m) => s + m.v, 0);
                  const mktForecast = mktData.map(m => ({ name: m.n, value: totalActRev > 0 ? Math.round(d[13] * (m.v / totalActRev)) : 0 }));
                  return (
                    <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                      <div style={{ width: "55%" }}>
                        <DualRingPie id="mktr" outerData={mktForecast} innerData={mktData.map(m => ({ name: m.n, value: m.v }))} outerColors={mktColors} innerColors={mktColors} height={200} />
                      </div>
                      <div style={{ flex: 1 }}>
                        {mktData.map((m, i) => {
                          const pctOfTotal = totalActRev > 0 ? (m.v / totalActRev * 100) : 0;
                          return (
                            <div key={i} style={{ display: "flex", alignItems: "center", gap: 4, padding: "3px 0", borderBottom: i < mktData.length - 1 ? "1px solid " + T.bd : "none" }}>
                              <div style={{ width: 6, height: 6, borderRadius: 1, background: m.c, flexShrink: 0 }} />
                              <span style={{ fontSize: 8, color: T.t3, flex: 1 }}>{m.n}</span>
                              <div style={{ textAlign: "right" }}>
                                <span style={{ fontSize: 10, fontWeight: 600, fontFamily: "'JetBrains Mono', monospace", color: m.c }}>{fm(m.v)}</span>
                                <span style={{ fontSize: 8, color: T.t4, marginLeft: 3 }}>{pctOfTotal.toFixed(0)}%</span>
                              </div>
                            </div>
                          );
                        })}
                        <div style={{ marginTop: 3, fontSize: 8, color: T.t4, fontStyle: "italic" }}>Online/Draft est. until Shopify API connected</div>
                      </div>
                    </div>
                  );
                })()}
                {/* Revenue adherence scores */}
                {(() => {
                  const revDelivery = d[13] > 0 ? (d[2] / d[13] * 100) : 0;
                  const revVsLY = d[21] > 0 ? (d[2] / d[21] * 100) : 0;
                  const delivColor = revDelivery >= 95 ? T.gn : revDelivery >= 80 ? T.am : T.rd;
                  const lyColor = revVsLY >= 105 ? T.gn : revVsLY >= 95 ? T.am : T.rd;
                  return (
                    <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
                      <div style={{ flex: 1, textAlign: "center", padding: "6px 4px", borderRadius: 6, background: T.cd, border: "1px solid " + T.bd }}>
                        <div style={{ fontSize: 8, color: T.t3, marginBottom: 2 }}>Delivery vs plan</div>
                        <div style={{ fontSize: 16, fontWeight: 700, fontFamily: "'JetBrains Mono', monospace", color: delivColor }}>{Math.round(revDelivery)}%</div>
                      </div>
                      <div style={{ flex: 1, textAlign: "center", padding: "6px 4px", borderRadius: 6, background: T.cd, border: "1px solid " + T.bd }}>
                        <div style={{ fontSize: 8, color: T.t3, marginBottom: 2 }}>vs LY</div>
                        <div style={{ fontSize: 16, fontWeight: 700, fontFamily: "'JetBrains Mono', monospace", color: lyColor }}>{Math.round(revVsLY)}%</div>
                      </div>
                    </div>
                  );
                })()}
              </div>
            </div>
          </div>
        )}

        {/* ═══ BUDGET ALLOCATOR + MER DECAY ═══ */}
        {chV === null && (
          <div className="fi" style={{ background: T.cd, border: "1px solid " + T.bd, borderRadius: 12, marginBottom: 14, overflow: "hidden" }}>
            <div className="acc" onClick={() => setAllocOpen(!allocOpen)} style={{ padding: "12px 16px", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
              <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                <div style={{ width: 24, height: 24, borderRadius: 5, display: "flex", alignItems: "center", justifyContent: "center", background: T.cy + "20", fontSize: 12, color: T.cy }}>$</div>
                <div>
                  <div style={{ fontSize: 13, fontWeight: 700 }}>Budget Allocator</div>
                  <div style={{ fontSize: 9, color: T.t3 }}>Channel budgets + MER decay modeling + forecast sync</div>
                </div>
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                <div style={{ display: "flex", gap: 10, fontSize: 10 }}>
                  <span style={{ color: T.t3 }}>Spend: <span style={{ fontFamily: "'JetBrains Mono', monospace", color: T.ac, fontWeight: 600 }}>{fm(projection.totalSp)}</span></span>
                  <span style={{ color: T.t3 }}>Rev: <span style={{ fontFamily: "'JetBrains Mono', monospace", color: T.gn, fontWeight: 600 }}>{fm(projection.rev)}</span></span>
                  <span style={{ color: T.t3 }}>MER: <span style={{ fontFamily: "'JetBrains Mono', monospace", color: projection.mer > effectiveMerCeiling ? T.rd : projection.mer > 16 ? T.am : T.gn, fontWeight: 600 }}>{projection.mer.toFixed(1)}%</span></span>
                </div>
                <span style={{ fontSize: 9, color: T.t3 }}>{allocOpen ? "▾" : "▸"}</span>
              </div>
            </div>

            {allocOpen && (
              <div style={{ padding: "0 16px 16px", borderTop: "1px solid " + T.bd }}>

                {/* ── OUTPUTS ── */}
                <div style={{ marginTop: 12, marginBottom: 14 }}>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6 }}>
                    <div style={{ fontSize: 8, color: T.t4, textTransform: "uppercase", letterSpacing: 1.5, fontWeight: 600 }}>Outputs</div>
                    {promoCtx.promo && spendMult.mult > 1.02 && (
                      <span style={{ fontSize: 8, color: T.cy, padding: "2px 6px", borderRadius: 3, background: T.cy + "12" }}>
                        Promo ramp active: {spendMult.mult.toFixed(2)}x | MER ceiling relaxed to {rec.effectiveCeiling.toFixed(1)}%
                      </span>
                    )}
                  </div>
                  <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 8 }}>
                    {[
                      { l: "Total spend", v: fk(projection.totalSp), sub: (projection.spDelta >= 0 ? "+" : "") + fc(projection.spDelta) + " vs fc", sc: projection.spDelta > 0 ? T.rd : T.gn },
                      { l: "Projected revenue", v: fk(Math.round(projection.rev)), sub: "Amz " + fc(Math.round(projection.amzRev)) + " + Shop " + fc(Math.round(projection.shopRev)), sc: projection.revDelta >= 0 ? T.gn : T.rd },
                      { l: "Projected MER", v: projection.mer.toFixed(1) + "%", sub: effectiveMerCeiling + "% ceiling" + (spendMult.mult > 1.02 ? " (relaxed)" : ""), sc: projection.mer > effectiveMerCeiling ? T.rd : projection.mer > 16 ? T.am : T.gn },
                      { l: "Blended ROAS", v: projection.roas.toFixed(1) + "x", sub: "total rev / total spend", sc: projection.roas > 5 ? T.gn : projection.roas > 3 ? T.am : T.rd },
                      { l: "Amazon ROAS", v: projection.amzRoas.toFixed(1) + "x", sub: "includes " + fc(Math.round(projection.halo)) + " halo", sc: projection.amzRoas > 5 ? T.gn : projection.amzRoas > 3 ? T.am : T.rd },
                      { l: "Shopify ROAS", v: projection.shopRoas.toFixed(1) + "x", sub: "Northbeam pending", sc: projection.shopRoas > 8 ? T.gn : projection.shopRoas > 5 ? T.am : T.rd },
                      { l: "Gross contribution", v: fm(projection.contrib), sub: "margin minus ad spend", sc: projection.contrib > 0 ? T.gn : T.rd },
                      { l: "LTV-adjusted", v: fm(projection.ltvContrib), sub: MARGIN.newCustPremium + "x new cust premium", sc: projection.ltvContrib > 0 ? T.gn : T.rd },
                    ].map((m, i) => (
                      <div key={i} style={{ background: T.bg, borderRadius: 6, padding: "10px 12px", border: "1px solid " + T.bd }}>
                        <div style={{ fontSize: 8, color: T.t4, marginBottom: 3 }}>{m.l}</div>
                        <div style={{ fontSize: 16, fontWeight: 700, fontFamily: "'JetBrains Mono', monospace", color: m.sc }}>{m.v}</div>
                        <div style={{ fontSize: 9, color: T.t4, marginTop: 2 }}>{m.sub}</div>
                      </div>
                    ))}
                  </div>
                </div>

                {/* ── INPUTS ── */}
                <div style={{ fontSize: 8, color: T.t4, textTransform: "uppercase", letterSpacing: 1.5, fontWeight: 600, marginBottom: 6 }}>Inputs</div>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 2fr", gap: 14 }}>

                  {/* Decay Chart */}
                  <div style={{ background: T.bg, borderRadius: 8, padding: 12, border: "1px solid " + T.bd }}>
                    <div style={{ fontSize: 9, color: T.t3, textTransform: "uppercase", letterSpacing: .6, fontWeight: 600, marginBottom: 8 }}>Amazon ROAS decay curve</div>
                    <ResponsiveContainer width="100%" height={180}>
                      <ComposedChart margin={{ top: 5, right: 5, bottom: 5, left: 5 }}>
                        <CartesianGrid strokeDasharray="3 3" stroke={T.bd} />
                        <XAxis dataKey="sp" type="number" domain={[6000, 28000]} tick={{ fontSize: 8, fill: T.t3 }} tickLine={false} axisLine={false} tickFormatter={v => fm(v)} />
                        <YAxis tick={{ fontSize: 8, fill: T.t3 }} tickLine={false} axisLine={false} tickFormatter={v => v + "x"} domain={[0, 10]} />
                        <Tooltip content={<Tip />} />
                        <Scatter data={amzScatter} fill={T.am + "66"} r={3} />
                        <Line data={decayCurve} dataKey="roas" type="monotone" stroke={T.am} strokeWidth={2} dot={false} />
                        <ReferenceLine x={budgets.amz} stroke={T.ac} strokeDasharray="4 4" strokeWidth={1.5} />
                      </ComposedChart>
                    </ResponsiveContainer>
                    <div style={{ fontSize: 9, color: T.t3, marginTop: 4 }}>
                      At <span style={{ color: T.ac, fontFamily: "'JetBrains Mono', monospace" }}>{fm(budgets.amz)}</span> spend: <span style={{ color: T.am, fontFamily: "'JetBrains Mono', monospace", fontWeight: 600 }}>{projection.amzRoas.toFixed(1)}x</span> ROAS
                    </div>
                    <div style={{ marginTop: 8, padding: "6px 8px", borderRadius: 5, background: T.ac + "08", fontSize: 9, color: T.t3, lineHeight: 1.4 }}>
                      Meta halo: logistic curve, caps at $10K/day (Northbeam will refine). Shopify: power law on non-Amazon spend. Google/Meta decay curves need attributed conversion APIs.
                    </div>
                  </div>

                  {/* Sliders + Recommendation */}
                  <div>
                    {/* Controls row: MER ceiling + Promo ramp */}
                    <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 8, marginBottom: 10 }}>
                      <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "8px 12px", borderRadius: 6, background: T.bg, border: "1px solid " + T.bd }}>
                        <span style={{ fontSize: 9, color: T.t3, textTransform: "uppercase", letterSpacing: .5, fontWeight: 600, whiteSpace: "nowrap" }}>MER cap</span>
                        <input type="range" min={10} max={30} step={0.5} value={merDrag !== null ? merDrag : effectiveMerCeiling} onChange={e => setMerDrag(Number(e.target.value))} onMouseUp={e => { setMerCeiling(Number(e.target.value)); setMerDrag(null); }} onTouchEnd={e => { setMerCeiling(Number(e.target.value)); setMerDrag(null); }} style={{ flex: 1, accentColor: T.rd, height: 4 }} />
                        <span style={{ fontSize: 13, fontWeight: 700, fontFamily: "'JetBrains Mono', monospace", color: T.rd, minWidth: 42, textAlign: "right", display: "inline-block" }}>{(merDrag !== null ? merDrag : effectiveMerCeiling).toFixed(1)}%</span>
                        {projection.mer > effectiveMerCeiling && <span style={{ fontSize: 8, padding: "2px 5px", borderRadius: 3, background: T.rd + "18", color: T.rd, fontWeight: 600 }}>OVER</span>}
                      </div>
                      <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "8px 12px", borderRadius: 6, background: T.bg, border: "1px solid " + T.bd }}>
                        <span style={{ fontSize: 9, color: T.cy, textTransform: "uppercase", letterSpacing: .5, fontWeight: 600, whiteSpace: "nowrap" }}>Lead-in</span>
                        <input type="range" min={3} max={14} step={1} value={rampLeadIn} onChange={e => setRampLeadIn(Number(e.target.value))} style={{ flex: 1, accentColor: T.cy, height: 4 }} />
                        <span style={{ fontSize: 13, fontWeight: 700, fontFamily: "'JetBrains Mono', monospace", color: T.cy, minWidth: 28 }}>{rampLeadIn}d</span>
                      </div>
                      <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "8px 12px", borderRadius: 6, background: T.bg, border: "1px solid " + T.bd }}>
                        <span style={{ fontSize: 9, color: T.am, textTransform: "uppercase", letterSpacing: .5, fontWeight: 600, whiteSpace: "nowrap" }}>Max ramp</span>
                        <input type="range" min={1.1} max={2.5} step={0.1} value={rampMult} onChange={e => setRampMult(Number(e.target.value))} style={{ flex: 1, accentColor: T.am, height: 4 }} />
                        <span style={{ fontSize: 13, fontWeight: 700, fontFamily: "'JetBrains Mono', monospace", color: T.am, minWidth: 32 }}>{rampMult.toFixed(1)}x</span>
                      </div>
                    </div>

                    {/* Channel budget sliders */}
                    <div style={{ display: "grid", gridTemplateColumns: "repeat(5, 1fr)", gap: 8, marginBottom: 10 }}>
                      {[
                        { key: "amz", label: "Amazon", min: 3000, max: 30000, step: 500, color: "#FF9900" },
                        { key: "ggl", label: "Google", min: 200, max: 8000, step: 100, color: "#4285F4" },
                        { key: "meta", label: "Meta", min: 50, max: 4000, step: 50, color: "#0668E1" },
                        { key: "msft", label: "Microsoft", min: 0, max: 3000, step: 50, color: "#00A4EF" },
                        { key: "wal", label: "Walmart", min: 0, max: 2000, step: 50, color: "#0071DC" },
                      ].map(ch => (
                        <div key={ch.key} style={{ background: T.bg, borderRadius: 6, padding: "8px 10px", border: "1px solid " + T.bd }}>
                          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 4 }}>
                            <span style={{ fontSize: 9, color: ch.color, fontWeight: 600 }}>{ch.label}</span>
                            <span style={{ fontSize: 11, fontWeight: 700, fontFamily: "'JetBrains Mono', monospace", color: T.tx }}>{fc(budgets[ch.key])}</span>
                          </div>
                          <input type="range" min={ch.min} max={ch.max} step={ch.step} value={budgets[ch.key]} onChange={e => setBudget(ch.key, Number(e.target.value))} style={{ width: "100%", accentColor: ch.color, height: 4 }} />
                          <div style={{ display: "flex", justifyContent: "space-between", fontSize: 8, color: T.t4 }}>
                            <span>{fc(ch.min)}</span>
                            <span>{fc(ch.max)}</span>
                          </div>
                        </div>
                      ))}
                    </div>

                    {/* Recommended mix */}
                    <div style={{ padding: 10, borderRadius: 8, background: T.bg, border: "1px solid " + T.cy + "30", marginBottom: 10 }}>
                      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
                        <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                          <div style={{ width: 6, height: 6, borderRadius: "50%", background: T.cy }} />
                          <span style={{ fontSize: 10, fontWeight: 600, color: T.cy, textTransform: "uppercase", letterSpacing: .5 }}>Recommended mix</span>
                          <span style={{ fontSize: 9, color: T.t3 }}>Max rev at {effectiveMerCeiling}% MER cap</span>
                        </div>
                        <div style={{ display: "flex", gap: 8, fontSize: 9 }}>
                          <span style={{ color: T.t3 }}>Rev: <span style={{ color: T.gn, fontWeight: 600, fontFamily: "'JetBrains Mono', monospace" }}>{fm(rec.totalRev)}</span></span>
                          <span style={{ color: T.t3 }}>MER: <span style={{ color: rec.mer > effectiveMerCeiling ? T.rd : T.gn, fontWeight: 600, fontFamily: "'JetBrains Mono', monospace" }}>{rec.mer.toFixed(1)}%</span></span>
                          <span style={{ color: T.t3 }}>ROAS: <span style={{ fontWeight: 600, fontFamily: "'JetBrains Mono', monospace" }}>{rec.roas.toFixed(1)}x</span></span>
                        </div>
                      </div>
                      <div style={{ display: "grid", gridTemplateColumns: "repeat(5, 1fr)", gap: 6 }}>
                        {[
                          { key: "amz", label: "Amazon", color: "#FF9900" },
                          { key: "ggl", label: "Google", color: "#4285F4" },
                          { key: "meta", label: "Meta", color: "#0668E1" },
                          { key: "msft", label: "Microsoft", color: "#00A4EF" },
                          { key: "wal", label: "Walmart", color: "#0071DC" },
                        ].map(ch => {
                          const cur = budgets[ch.key];
                          const suggested = rec[ch.key];
                          const delta = suggested - cur;
                          const pct = projection.totalSp > 0 ? (suggested / projection.totalSp * 100) : 0;
                          return (
                            <div key={ch.key} style={{ padding: "5px 7px", borderRadius: 5, background: T.cd, border: "1px solid " + T.bd }}>
                              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 2 }}>
                                <span style={{ fontSize: 8, color: ch.color, fontWeight: 600 }}>{ch.label}</span>
                                <span style={{ fontSize: 8, color: T.t4 }}>{pct.toFixed(0)}%</span>
                              </div>
                              <div style={{ fontSize: 13, fontWeight: 700, fontFamily: "'JetBrains Mono', monospace", color: T.tx }}>{fc(suggested)}</div>
                              {delta !== 0 && (
                                <div style={{ fontSize: 9, fontWeight: 600, color: delta > 0 ? T.gn : T.am, marginTop: 1 }}>
                                  {delta > 0 ? "↑+" : "↓"}{fc(Math.abs(delta))}
                                </div>
                              )}
                              {delta === 0 && <div style={{ fontSize: 9, color: T.t4, marginTop: 1 }}>No change</div>}
                            </div>
                          );
                        })}
                      </div>
                      <button onClick={() => setBudgets({ amz: rec.amz, ggl: rec.ggl, meta: rec.meta, msft: rec.msft, wal: rec.wal })} style={{ marginTop: 8, padding: "5px 14px", borderRadius: 5, border: "1px solid " + T.cy, background: T.cy + "18", color: T.cy, fontSize: 10, fontWeight: 600, cursor: "pointer", fontFamily: "'Outfit', sans-serif" }}>
                        Apply recommended mix
                      </button>
                    </div>

                    {/* Integration status + Push */}
                    <div style={{ padding: "8px 12px", borderRadius: 6, background: T.bg, border: "1px solid " + T.bd }}>
                      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6 }}>
                        <div style={{ fontSize: 8, color: T.t4, textTransform: "uppercase", letterSpacing: 1, fontWeight: 600 }}>API connections</div>
                        <button style={{ padding: "5px 14px", borderRadius: 5, border: "1px solid " + T.cy, background: T.cy + "18", color: T.cy, fontSize: 10, fontWeight: 600, cursor: "pointer", fontFamily: "'Outfit', sans-serif", whiteSpace: "nowrap" }}>
                          Push budgets to APIs
                        </button>
                      </div>
                      <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                        {[
                          { n: "Northbeam MTA", s: "pending", note: "Attribution source of truth" },
                          { n: "Amazon Ads", s: "pending", note: "Bid + budget push" },
                          { n: "Google Ads", s: "pending", note: "Budget + CPA targets" },
                          { n: "Meta Marketing", s: "pending", note: "Budget + ROAS targets" },
                          { n: "Shopify Admin", s: "pending", note: "Revenue + order data" },
                        ].map((api, i) => (
                          <div key={i} style={{ display: "flex", alignItems: "center", gap: 4, padding: "3px 8px", borderRadius: 4, background: T.cd, border: "1px solid " + T.bd, fontSize: 9 }}>
                            <div style={{ width: 5, height: 5, borderRadius: "50%", background: api.s === "live" ? T.gn : api.s === "pending" ? T.am : T.t4 }} />
                            <span style={{ color: T.t2, fontWeight: 500 }}>{api.n}</span>
                            <span style={{ color: T.t4 }}>{api.note}</span>
                          </div>
                        ))}
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>
        )}


        {/* ═══ ROW 2: WEEKLY / MTD / QTD ═══ */}
        {chV === null && (
          <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 12, marginBottom: 16 }}>
            {row2.map((b) => {
              const dd = b.data;
              const isOpen = expanded === b.key;
              const spPct = dd.spFc > 0 ? Math.round(dd.spend / dd.spFc * 100) : 0;
              const rvPct = dd.revFc > 0 ? Math.round(dd.rev / dd.revFc * 100) : 0;
              const merVal = dd.mer;
              const roas = dd.spend > 0 ? (dd.rev / dd.spend).toFixed(1) : "0";
              // Max for bar scaling
              const revMax = Math.max(dd.rev, dd.revFc, dd.revLy, dd.rev24 || 0) * 1.15;
              const spMax = Math.max(dd.spend, dd.spFc, dd.spLy, dd.sp24 || 0) * 1.15;
              return (
                <div key={b.key} style={{ gridColumn: isOpen ? "1 / -1" : undefined, background: T.cd, border: "1px solid " + T.bd, borderRadius: 10, overflow: "hidden", borderTop: "2px solid " + b.color }}>
                  <div className="acc" onClick={() => toggle(b.key)} style={{ padding: "12px 14px" }}>
                    {/* Header */}
                    <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10 }}>
                      <span style={{ fontSize: 13, fontWeight: 700 }}>{b.label}</span>
                      <span style={{ fontSize: 9, color: T.t3 }}>{b.sub}</span>
                      <div style={{ marginLeft: "auto", display: "flex", alignItems: "center", gap: 8 }}>
                        <span style={{ fontSize: 10, fontWeight: 600, color: merVal > 20 ? T.rd : merVal > 16 ? T.am : T.gn, fontFamily: "'JetBrains Mono', monospace" }}>{merVal.toFixed(1)}% MER</span>
                        <span style={{ fontSize: 10, color: T.t3, fontFamily: "'JetBrains Mono', monospace" }}>{roas}x ROAS</span>
                        <span style={{ fontSize: 9, color: T.t3 }}>{isOpen ? "▾" : "▸"}</span>
                      </div>
                    </div>

                    {/* Two-column: Spend | Revenue */}
                    <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
                      {/* Spend */}
                      <div>
                        <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 4 }}>
                          <span style={{ fontSize: 9, color: T.t3, textTransform: "uppercase", letterSpacing: .5, fontWeight: 600 }}>Spend</span>
                          <span style={{ fontSize: 9, fontWeight: 600, color: spPct > 105 ? T.rd : spPct > 95 ? T.gn : T.am, fontFamily: "'JetBrains Mono', monospace" }}>{spPct}%</span>
                        </div>
                        {/* Stacked bar viz */}
                        {[
                          { label: "2026", val: dd.spend, color: T.ac, bold: true },
                          { label: "Forecast", val: dd.spFc, color: T.am, dashed: true },
                          { label: "2025", val: dd.spLy, color: "#8a919c" },
                          { label: "2024", val: dd.sp24, color: "#555b64" },
                        ].map((row, ri) => (
                          <div key={ri} style={{ display: "flex", alignItems: "center", gap: 4, marginBottom: 2 }}>
                            <span style={{ fontSize: 8, color: row.color, width: 36, textAlign: "right", fontWeight: row.bold ? 600 : 400 }}>{row.label}</span>
                            <div style={{ flex: 1, height: row.bold ? 10 : row.dashed ? 8 : 6, background: T.bg, borderRadius: 2, overflow: "hidden", position: "relative" }}>
                              <div style={{ height: "100%", width: (spMax > 0 ? Math.min(row.val / spMax * 100, 100) : 0) + "%", background: row.color, opacity: row.dashed ? 0.35 : row.bold ? 1 : 0.5, borderRadius: 2 }} />
                            </div>
                            <span style={{ fontSize: 9, fontFamily: "'JetBrains Mono', monospace", color: row.color, width: 42, textAlign: "right", fontWeight: row.bold ? 700 : 400 }}>{fm(row.val)}</span>
                          </div>
                        ))}
                        <div style={{ fontSize: 9, fontWeight: 600, color: (dd.spend - dd.spFc) > 0 ? T.rd : T.gn, marginTop: 2, textAlign: "right", fontFamily: "'JetBrains Mono', monospace" }}>
                          {(dd.spend - dd.spFc) > 0 ? "+" : ""}{fm(dd.spend - dd.spFc)} vs forecast
                        </div>
                      </div>

                      {/* Revenue */}
                      <div>
                        <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 4 }}>
                          <span style={{ fontSize: 9, color: T.t3, textTransform: "uppercase", letterSpacing: .5, fontWeight: 600 }}>Revenue</span>
                          <span style={{ fontSize: 9, fontWeight: 600, color: rvPct >= 95 ? T.gn : rvPct >= 80 ? T.am : T.rd, fontFamily: "'JetBrains Mono', monospace" }}>{rvPct}%</span>
                        </div>
                        {[
                          { label: "2026", val: dd.rev, color: T.gn, bold: true },
                          { label: "Forecast", val: dd.revFc, color: T.am, dashed: true },
                          { label: "2025", val: dd.revLy, color: "#8a919c" },
                          { label: "2024", val: dd.rev24, color: "#555b64" },
                        ].map((row, ri) => (
                          <div key={ri} style={{ display: "flex", alignItems: "center", gap: 4, marginBottom: 2 }}>
                            <span style={{ fontSize: 8, color: row.color, width: 36, textAlign: "right", fontWeight: row.bold ? 600 : 400 }}>{row.label}</span>
                            <div style={{ flex: 1, height: row.bold ? 10 : row.dashed ? 8 : 6, background: T.bg, borderRadius: 2, overflow: "hidden" }}>
                              <div style={{ height: "100%", width: (revMax > 0 ? Math.min(row.val / revMax * 100, 100) : 0) + "%", background: row.color, opacity: row.dashed ? 0.35 : row.bold ? 1 : 0.5, borderRadius: 2 }} />
                            </div>
                            <span style={{ fontSize: 9, fontFamily: "'JetBrains Mono', monospace", color: row.color, width: 42, textAlign: "right", fontWeight: row.bold ? 700 : 400 }}>{fm(row.val)}</span>
                          </div>
                        ))}
                        <div style={{ fontSize: 9, fontWeight: 600, color: (dd.rev - dd.revFc) >= 0 ? T.gn : T.rd, marginTop: 2, textAlign: "right", fontFamily: "'JetBrains Mono', monospace" }}>
                          {(dd.rev - dd.revFc) >= 0 ? "+" : ""}{fm(dd.rev - dd.revFc)} vs forecast
                        </div>
                      </div>
                    </div>
                  </div>
                  {isOpen && (
                    <div style={{ padding: "0 14px 12px", borderTop: "1px solid " + T.bd }}>
                      <BriefingCharts data={b.chartData} title={b.label} />
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}

        {/* ═══ NAV: Overview + Channels ═══ */}
        {chV === null && (
          <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 12, paddingBottom: 10, borderBottom: "1px solid " + T.bd }}>
            <span style={{ fontSize: 12, fontWeight: 600, color: T.ac, paddingRight: 8, borderRight: "1px solid " + T.bd, marginRight: 4 }}>Overview</span>
            {CN.map((ch, i) => (
              <button key={i} onClick={() => setChV(i)} style={{ display: "flex", alignItems: "center", gap: 5, padding: "5px 10px", borderRadius: 6, border: "1px solid " + T.bd, background: T.cd, cursor: "pointer", fontSize: 10, color: T.t2, fontFamily: "'Outfit', sans-serif" }}>
                <Logo ch={ch} s={16} />{ch}
              </button>
            ))}
          </div>
        )}

        {/* ═══ CHANNEL DETAIL ═══ */}
        {chV !== null && (
          <div className="fi">
            <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 16 }}>
              <button onClick={() => setChV(null)} style={{ padding: "5px 12px", borderRadius: 6, border: "1px solid " + T.bd, background: T.cd, color: T.t2, cursor: "pointer", fontSize: 11, fontFamily: "'Outfit', sans-serif" }}>{"←"} Back</button>
              <Logo ch={CN[chV]} s={28} />
              <div style={{ fontSize: 18, fontWeight: 700 }}>{CN[chV]}</div>
              <div style={{ marginLeft: "auto", display: "flex", gap: 4 }}>
                {CN.map((ch, i) => (
                  <button key={i} onClick={() => setChV(i)} style={{ padding: "4px 8px", borderRadius: 5, border: "1px solid " + (chV === i ? CC[i] : T.bd), background: chV === i ? CC[i] + "22" : T.cd, cursor: "pointer", display: "flex", alignItems: "center" }}><Logo ch={ch} s={16} /></button>
                ))}
              </div>
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 10, marginBottom: 16 }}>
              {[
                { l: "YTD Actual", v: fk(actuals.reduce((s, r) => s + (r[CA[chV]] || 0), 0)), c: CC[chV] },
                { l: "YTD Forecast", v: fk(actuals.reduce((s, r) => s + (r[CF[chV]] || 0), 0)), c: T.am },
                { l: "YTD LY", v: CL[chV] !== null ? fk(actuals.reduce((s, r) => s + (r[CL[chV]] || 0), 0)) : "N/A", c: T.pu },
                { l: "Yesterday", v: fk(latest[CA[chV]] || 0), c: T.tx },
              ].map((c, i) => (
                <div key={i} style={{ background: T.cd, border: "1px solid " + T.bd, borderRadius: 10, padding: 12, borderTop: "2px solid " + c.c }}>
                  <div style={{ fontSize: 9, color: T.t3, textTransform: "uppercase", letterSpacing: .5, marginBottom: 4 }}>{c.l}</div>
                  <div style={{ fontSize: 20, fontWeight: 700, fontFamily: "'JetBrains Mono', monospace", color: c.c }}>{c.v}</div>
                </div>
              ))}
            </div>
            <div style={{ background: T.cd, border: "1px solid " + T.bd, borderRadius: 12, padding: 16, marginBottom: 16 }}>
              <div style={{ fontSize: 13, fontWeight: 600, marginBottom: 12 }}>{CN[chV]} Spend: Actual vs Forecast vs LY</div>
              <ResponsiveContainer width="100%" height={200}>
                <ComposedChart data={actuals.map(r => ({ d: r[0], Actual: r[CA[chV]] || 0, Forecast: r[CF[chV]] || 0, LY: CL[chV] !== null ? (r[CL[chV]] || 0) : 0 }))} margin={{ top: 5, right: 5, bottom: 5, left: 5 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke={T.bd} />
                  <XAxis dataKey="d" tick={{ fontSize: 9, fill: T.t3 }} tickLine={false} interval={8} />
                  <YAxis tick={{ fontSize: 9, fill: T.t3 }} tickLine={false} axisLine={false} tickFormatter={v => fm(v)} width={50} />
                  <Tooltip content={<Tip />} />
                  {CL[chV] !== null && <Area type="monotone" dataKey="LY" fill={T.pu + "15"} stroke={T.pu} strokeWidth={1.5} strokeDasharray="4 4" />}
                  <Line type="monotone" dataKey="Forecast" stroke={T.am} strokeWidth={1.5} strokeDasharray="6 3" dot={false} />
                  <Line type="monotone" dataKey="Actual" stroke={CC[chV]} strokeWidth={2.5} dot={false} />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
            <div style={{ background: T.cd, border: "1px solid " + T.bd, borderRadius: 12, overflow: "hidden", maxHeight: 360 }}>
              <div style={{ overflowY: "auto", maxHeight: 360 }}>
                <table className="tbl"><thead><tr><th style={{ textAlign: "left" }}>2026</th><th style={{ textAlign: "left", color: T.t4 }}>2025</th><th style={{ textAlign: "left", color: T.t4 + "88" }}>2024</th><th>Actual</th><th>Forecast</th><th>Delta</th><th>LY</th><th>YoY</th></tr></thead>
                <tbody>{R.map((r, i) => {
                  const a = r[CA[chV]] || 0, f = r[CF[chV]] || 0, ly = CL[chV] !== null ? (r[CL[chV]] || 0) : 0;
                  const h = has(r), delta = h ? a - f : 0, isToday = actuals.length > 0 && r[0] === actuals[actuals.length-1][0];
                  return (
                    <tr key={i} className={isToday ? "today" : ""}>
                      <td style={{ color: isToday ? T.am : h ? T.tx : T.t3 }}>{r[0]} <span style={{ color: T.t3, fontSize: 10 }}>{r[1]}</span></td>
                      <td style={{ color: T.t4, fontSize: 10 }}>{r[20]}</td>
                      <td style={{ color: T.t4 + "77", fontSize: 10 }}>{r[27]}</td>
                      <td style={{ color: h ? CC[chV] : T.t4, fontWeight: h ? 600 : 400 }}>{h ? fk(a) : "—"}</td>
                      <td style={{ color: T.am }}>{fk(f)}</td>
                      <td style={{ color: h ? (delta > 0 ? T.rd : T.gn) : T.t4, fontWeight: 600 }}>{h ? (delta > 0 ? "+" : "") + fk(delta) : "—"}</td>
                      <td style={{ color: ly > 0 ? T.pu : T.t4 }}>{ly > 0 ? fk(ly) : "—"}</td>
                      <td style={{ color: h && ly > 0 ? (a > ly ? T.rd : T.gn) : T.t4 }}>{h && ly > 0 ? pc(yoy(a, ly)) : "—"}</td>
                    </tr>
                  );
                })}</tbody></table>
              </div>
            </div>
          </div>
        )}

        {/* ═══ DATA TABLE ═══ */}
        {chV === null && (
          <div className="fi" style={{ background: T.cd, border: "1px solid " + T.bd, borderRadius: 12, overflow: "hidden" }}>
            <div ref={tableRef} style={{ overflowY: "auto", maxHeight: 520, overflowX: "auto" }}>
              <table className="tbl"><thead>
                <tr>
                  <th className="gh" colSpan={3} style={{ textAlign: "center", position: "sticky", left: 0, background: T.bg2, zIndex: 5 }}>Date</th>
                  <th className="gh sep" colSpan={5} style={{ textAlign: "center" }}>Revenue</th>
                  <th className="gh sep" colSpan={5} style={{ textAlign: "center" }}>Spend Totals</th>
                  <th className="gh sep" colSpan={12} style={{ textAlign: "center" }}>Spend by Channel</th>
                  <th className="gh sep" colSpan={1} style={{ textAlign: "center" }}>Efficiency</th>
                </tr>
                <tr>
                  <th className="sh" style={{ textAlign: "left", position: "sticky", left: 0, background: T.bg2, zIndex: 4, minWidth: 65, padding: "4px 4px 4px 6px" }}>2026</th>
                  <th className="sh" style={{ textAlign: "left", color: "#8a919c", padding: "4px 4px" }}>2025</th>
                  <th className="sh" style={{ textAlign: "left", color: "#555b64", padding: "4px 6px 4px 4px" }}>2024</th>
                  <th className="sh sep">2026</th><th className="sh">Forecast</th><th className="sh" style={{ textAlign: "center" }}>{"Δ"}</th><th className="sh" style={{ color: "#8a919c" }}>2025</th><th className="sh" style={{ color: "#555b64" }}>2024</th>
                  <th className="sh sep">2026</th><th className="sh">Forecast</th><th className="sh" style={{ textAlign: "center" }}>{"Δ"}</th><th className="sh" style={{ color: "#8a919c" }}>2025</th><th className="sh" style={{ color: "#555b64" }}>2024</th>
                  <th className="sh sep">Amazon</th><th className="sh">Fc</th><th className="sh" style={{ color: "#8a919c" }}>25</th><th className="sh" style={{ color: "#555b64" }}>24</th>
                  <th className="sh sep">Google</th><th className="sh">Fc</th><th className="sh" style={{ color: "#8a919c" }}>25</th><th className="sh" style={{ color: "#555b64" }}>24</th>
                  <th className="sh sep">Meta</th><th className="sh">Fc</th><th className="sh" style={{ color: "#8a919c" }}>25</th><th className="sh" style={{ color: "#555b64" }}>24</th>
                  <th className="sh sep" style={{ textAlign: "center" }}>MER</th>
                </tr>
              </thead>
              <tbody>{R.map((r, i) => {
                const h = has(r), isToday = actuals.length > 0 && r[0] === actuals[actuals.length-1][0], isSun = i === lastSunIdx;
                const rd = h ? r[2] - r[13] : 0, sd = h ? r[3] - r[14] : 0;
                const pc2 = getPromoContext(r[0]);
                const prevPc = i > 0 ? getPromoContext(R[i-1][0]) : { promo: null };
                const isNewPromo = pc2.promo && pc2.promo !== prevPc.promo;
                const pColor = PROMO_COLORS[pc2.promo] || T.bd;
                const phaseIcon = pc2.phase === "lead-in" ? "▴" : pc2.phase === "lead-out" ? "▾" : "";
                return (
                  <tr key={i} className={isToday ? "today" : ""} data-sun={isSun ? "1" : undefined}>
                    <td style={{ position: "sticky", left: 0, background: T.cd, zIndex: 1, color: isToday ? T.am : h ? T.tx : T.t3, padding: "3px 4px 3px 6px", borderLeft: pc2.promo ? "3px solid " + pColor : "3px solid transparent" }}>
                      <div style={{ display: "flex", alignItems: "center", gap: 3 }}>
                        <span>{r[0]} <span style={{ color: T.t3, fontSize: 9 }}>{r[1]}</span></span>
                        {phaseIcon && <span style={{ fontSize: 7, color: pColor, opacity: 0.7 }}>{phaseIcon}</span>}
                      </div>
                      {isNewPromo && <div style={{ fontSize: 7, color: pColor, fontWeight: 600, lineHeight: 1, marginTop: 1, letterSpacing: .3, textTransform: "uppercase" }}>{pc2.promo}</div>}
                    </td>
                    <td style={{ color: "#8a919c", fontSize: 10, fontFamily: "'Outfit', sans-serif", padding: "3px 4px" }}>{r[20]}</td>
                    <td style={{ color: "#555b64", fontSize: 10, fontFamily: "'Outfit', sans-serif", padding: "3px 6px 3px 4px" }}>{r[27]}</td>
                    <td className="sep" style={{ color: h ? T.ac : T.t4, fontWeight: h ? 600 : 400 }}>{h ? fk(r[2]) : "—"}</td>
                    <td style={{ color: T.am }}>{fc(r[13])}</td>
                    <td style={{ color: h ? (rd >= 0 ? T.gn : T.rd) : T.t4, fontWeight: 600, textAlign: "center" }}>{h ? (rd >= 0 ? "+" : "") + fc(rd) : "—"}</td>
                    <td style={{ color: "#8a919c" }}>{fc(r[21])}</td>
                    <td style={{ color: "#555b64" }}>{fc(r[28])}</td>
                    <td className="sep" style={{ color: h ? T.ac : T.t4, fontWeight: h ? 600 : 400 }}>{h ? fk(r[3]) : "—"}</td>
                    <td style={{ color: T.am }}>{fc(r[14])}</td>
                    <td style={{ color: h ? (sd > 0 ? T.rd : T.gn) : T.t4, fontWeight: 600, textAlign: "center" }}>{h ? (sd > 0 ? "+" : "") + fc(sd) : "—"}</td>
                    <td style={{ color: "#8a919c" }}>{fc(r[22])}</td>
                    <td style={{ color: "#555b64" }}>{fc(r[29])}</td>
                    <td className="sep" style={{ color: h ? T.ac : T.t4 }}>{h ? fc(r[8]) : "—"}</td>
                    <td style={{ color: T.am, fontSize: 10 }}>{fc(r[15])}</td>
                    <td style={{ color: "#8a919c", fontSize: 10 }}>{fc(r[23])}</td>
                    <td style={{ color: "#555b64", fontSize: 10 }}>{"—"}</td>
                    <td className="sep" style={{ color: h ? T.ac : T.t4 }}>{h ? fc(r[9]) : "—"}</td>
                    <td style={{ color: T.am, fontSize: 10 }}>{fc(r[16])}</td>
                    <td style={{ color: "#8a919c", fontSize: 10 }}>{fc(r[24])}</td>
                    <td style={{ color: "#555b64", fontSize: 10 }}>{"—"}</td>
                    <td className="sep" style={{ color: h ? T.ac : T.t4 }}>{h ? fc(r[10]) : "—"}</td>
                    <td style={{ color: T.am, fontSize: 10 }}>{fc(r[17])}</td>
                    <td style={{ color: "#8a919c", fontSize: 10 }}>{fc(r[25])}</td>
                    <td style={{ color: "#555b64", fontSize: 10 }}>{"—"}</td>
                    <td className="sep" style={{ color: r[4] > 0 ? (r[4] > 20 ? T.rd : r[4] > 16 ? T.am : T.gn) : T.t4, textAlign: "center" }}>{r[4] > 0 ? r[4] + "%" : "—"}</td>
                  </tr>
                );
              })}</tbody></table>
            </div>
          </div>
        )}


        <div style={{ marginTop: 20, padding: "12px 0", borderTop: "1px solid " + T.bd, display: "flex", justifyContent: "space-between", fontSize: 9, color: T.t3 }}>
          <span>SSM Enterprises | Marketing Intelligence v6.0</span>
          <span>{actuals.length}d actual | DOW-matched | 5 channels | 3 marketplaces</span>
        </div>
      </div>
    </div>
  );
}

// ═══ CONTINUOUS TESTING ORCHESTRATOR ═══
// Latin square rotation ensures every DMA group appears in every arm over 5 cycles.
// After each test: auto-analyze → update coefficients → schedule next.
const LATIN_SQUARE = [[0,1,2,3,4],[1,2,3,4,0],[2,3,4,0,1],[3,4,0,1,2],[4,0,1,2,3]];
const DMA_GROUPS = [
  { name: "Large", dmas: ["Dallas TX","Houston TX","Atlanta GA","Phoenix AZ","Tampa FL"] },
  { name: "Mid-A", dmas: ["Denver CO","Charlotte NC","Nashville TN","Orlando FL","San Antonio TX"] },
  { name: "Mid-B", dmas: ["Austin TX","Columbus OH","Indianapolis IN","Kansas City MO","Raleigh NC"] },
  { name: "Small-A", dmas: ["Richmond VA","Louisville KY","Memphis TN","Oklahoma City OK","Greenville SC"] },
  { name: "Small-B", dmas: ["Birmingham AL","Tulsa OK","Knoxville TN","Little Rock AR"] },
];

const TEST_SCHEDULE = [
  { cycle: 1, ch: "Meta", start: "4/6", end: "4/26", analysis: "5/3", resume: "5/10", rot: 0 },
  { cycle: 2, ch: "Google", start: "5/11", end: "5/31", analysis: "6/7", resume: "6/14", rot: 1 },
  { cycle: 3, ch: "Microsoft", start: "6/15", end: "7/5", analysis: "7/12", resume: "7/19", rot: 2 },
  { cycle: 4, ch: "Meta", start: "7/20", end: "8/9", analysis: "8/16", resume: "8/23", rot: 3 },
  { cycle: 5, ch: "Google", start: "8/24", end: "9/13", analysis: "9/20", resume: "9/27", rot: 4 },
  { cycle: 6, ch: "Microsoft", start: "9/28", end: "10/18", analysis: "10/25", resume: "11/1", rot: 0 },
];

function getTestPhase(dateStr) {
  const [m, d] = parseMD(dateStr);
  const doy = dayOfYear(m, d);
  for (const t of TEST_SCHEDULE) {
    const [sm, sd] = parseMD(t.start);
    const [em, ed] = parseMD(t.end);
    const [am, ad] = parseMD(t.analysis);
    const [rm, rd] = parseMD(t.resume);
    const sDoy = dayOfYear(sm, sd), eDoy = dayOfYear(em, ed);
    const aDoy = dayOfYear(am, ad), rDoy = dayOfYear(rm, rd);
    if (doy >= sDoy && doy <= eDoy) return { ...t, phase: "testing", day: doy - sDoy + 1, totalDays: eDoy - sDoy + 1 };
    if (doy > eDoy && doy <= aDoy) return { ...t, phase: "lag", day: doy - eDoy };
    if (doy > aDoy && doy <= rDoy) return { ...t, phase: "washout", day: doy - aDoy };
  }
  return { phase: "idle" };
}

